/* Financial data stays in server-backed spaces. This client keeps no persistent cache. */
'use strict';
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const app = $('#app');
const modal = $('#modal');
const TODAY = new Date().toLocaleDateString('en-CA', {timeZone: 'America/Manaus'});
const CURRENT_MONTH = TODAY.slice(0, 7);
const ui = {session:null, spaceId:null, state:null, page:'home', month:CURRENT_MONTH, months:12, reportBasis:'purchase', filter:'all', search:'', authMode:'login', busy:false, simulation:null, technicalUsers:null, technicalNextOffset:null, technicalTotal:0};
const NAV = [['home','home','Início'],['entries','arrows','Movimentações'],['due','calendar','A pagar e a receber'],['cards','card','Cartões e faturas'],['debts','layers','Parcelamentos e dívidas'],['future','chart','Futuro financeiro'],['categories','grid','Categorias e locais'],['reports','report','Relatórios e orçamento'],['settings','settings','Configurações']];
const PATHS = {
  home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',
  arrows:'M4 7h15m-4-4 4 4-4 4M20 17H5m4-4-4 4 4 4',
  calendar:'M4 5h16v16H4zM16 3v4M8 3v4M4 10h16M8 14h2m4 0h2m-8 4h2',
  card:'M3 5h18v14H3zM3 10h18M6 15h4',layers:'m3 7 9-4 9 4-9 4zM3 12l9 4 9-4M3 17l9 4 9-4',
  chart:'M4 3v17h17M7 14l4-5 4 3 6-8',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',
  report:'M5 3h10l4 4v14H5zM14 3v5h5M8 17v-3m4 3v-6m4 6v-4',
  settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3l-1 3-3 1-2 3 2 2-1 4 3 2 3-1 3 2 3-2 3-1v-4l2-2-2-3-3-1-1-3z',
  plus:'M12 5v14M5 12h14',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',wallet:'M3 6h16v14H3zM3 6l13-3v3M15 11h6v5h-6z',
  clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 7v6l4 2',arrowup:'M12 19V5m-6 6 6-6 6 6',arrowdown:'M12 5v14m-6-6 6 6 6-6',
  check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',logout:'M9 4H4v16h5M10 12h11m-4-4 4 4-4 4',
  shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-6',leaf:'M20 3C7 3 3 8 4 15c1 8 13 7 16-12M6 19 17 7',
  search:'M11 3a8 8 0 1 0 0 16 8 8 0 0 0 0-16m6 14 5 5',users:'M9 4a4 4 0 1 0 0 8 4 4 0 0 0 0-8M2 21v-3a5 5 0 0 1 5-5h4a5 5 0 0 1 5 5v3M17 4a4 4 0 0 1 0 8m1 2a5 5 0 0 1 4 5v2',
  info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 11v6M12 7v1',bank:'m3 8 9-5 9 5H3m2 3v7m5-7v7m4-7v7m5-7v7M3 21h18',
  pix:'m12 3 9 9-9 9-9-9zM5 10h4l3 3 3-3h4M5 14h4l3-3 3 3h4',bell:'M6 9a6 6 0 0 1 12 0v6l3 3H3l3-3zM10 21h4',menu:'M4 6h16M4 12h16M4 18h16',refresh:'M20 8a8 8 0 1 0 0 8M20 3v5h-5',briefcase:'M3 7h18v14H3zM8 7V3h8v4M3 12h18M10 12v3h4v-3'
};
function icon(name, extra=''){return `<svg class="icon ${extra}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${PATHS[name]||PATHS.layers}"/></svg>`;}
function esc(v){return String(v??'').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
const money = n => new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format((Number.isSafeInteger(n)?n:0)/100);
function moneyInput(n){const value=Number.isSafeInteger(n)?n:0;return `${value<0?'-':''}${Math.floor(Math.abs(value)/100)},${String(Math.abs(value)%100).padStart(2,'0')}`;}
function cents(value){
  let text=String(value??'').trim().replace(/^R\$\s*/, '');
  const negative=text.startsWith('-');
  if(negative)text=text.slice(1);
  let whole, fraction='';
  if(/^\d{1,3}(?:\.\d{3})+(?:,\d{1,2})?$/.test(text)){
    [whole,fraction='']=text.split(',');whole=whole.replace(/\./g,'');
  }else if(/^\d+(?:,\d{1,2})?$/.test(text)){
    [whole,fraction='']=text.split(',');
  }else if(/^\d+\.\d{1,2}$/.test(text)){
    [whole,fraction]=text.split('.');
  }else throw Error('Informe um valor como 1.000,00 ou 333,33, com até duas casas decimais.');
  const result=Number(whole)*100+Number(fraction.padEnd(2,'0'));
  if(!Number.isSafeInteger(result))throw Error('Valor acima do limite permitido.');
  return negative?-result:result;
}
function date(d){if(!d)return '—';const p=String(d).slice(0,10).split('-');return p.length===3?`${p[2]}/${p[1]}/${p[0]}`:esc(d);}
function monthLabel(m, long=false){if(!m)return '—';return new Intl.DateTimeFormat('pt-BR',{month:long?'long':'short',year:long?'numeric':undefined,timeZone:'UTC'}).format(new Date(`${m}-15T12:00:00Z`)).replace('.','');}
function option(id,label,selected=''){return `<option value="${esc(id)}"${String(id)===String(selected)?' selected':''}>${esc(label)}</option>`;}
function sum(items,key='amount_cents'){return items.reduce((a,b)=>a+(Number.isSafeInteger(b[key])?b[key]:0),0);}
function list(key){return ui.state?.[key]||[];}
function byId(key,id){return list(key).find(x=>String(x.id)===String(id));}
function label(key,id){return byId(key,id)?.name||byId(key,id)?.description||'—';}
function person(id){const p=list('members').find(x=>String(x.user_id)===String(id)||String(x.id)===String(id));return p?.display_name||p?.username||'Não informado';}
function writable(){return ui.state?.space?.role!=='reader';}
function admin(){return ui.state?.space?.role==='admin';}
function technicalAdmin(){return ui.session?.user?.technical_admin===true;}
function participantIdentity(member){
  const ids=[];
  if(member.user_id!==undefined&&member.user_id!==null)ids.push(`Usuário #${esc(member.user_id)}`);
  if(member.id!==undefined&&member.id!==null)ids.push(`Vínculo #${esc(member.id)}`);
  return ids.join(' · ')||'Identificador não informado';
}
function participantStatus(member){
  const active=typeof member.is_active==='boolean'?member.is_active:member.status==='active'?true:['blocked','pending_or_blocked'].includes(member.status)?false:null;
  return `<span class="tag${active===true?' tag-green':active===false?' tag-red':''}">${active===true?'Ativo':active===false?'Bloqueado':'Situação não informada'}</span>`;
}
function ownParticipant(member){
  if(member.user_id!==undefined&&member.user_id!==null)return String(member.user_id)===String(ui.session.user.id);
  return Boolean(member.username)&&String(member.username).toLowerCase()===String(ui.session.user.username||'').toLowerCase();
}
function initial(name){return String(name||'O').split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase();}
function button(action,text,ico='plus',style='primary',data=''){return `<button class="btn btn-${style}" data-action="${action}" ${data}>${icon(ico)}${esc(text)}</button>`;}
function empty(title,description,action='',text='',ico='leaf',compact=false){return `<div class="empty${compact?' compact':''}">${icon(ico)}<b>${esc(title)}</b><p>${esc(description)}</p>${action&&writable()?button(action,text||'Começar'):''}</div>`;}
function badge(status){const map={paid:['Pago','green'],received:['Recebido','green'],pending:['Pendente',''],partial:['Parcialmente paga','blue'],overdue:['Em atraso','red'],cancelled:['Cancelado',''],active:['Ativo','green'],archived:['Arquivado','']};const [text,tone]=map[status]||[status||'Pendente',''];return `<span class="tag ${tone?'tag-'+tone:''}">${esc(text)}</span>`;}
function setToast(message,retry){const target=$('#toast');target.replaceChildren();const span=document.createElement('span');span.textContent=message;target.append(span);if(retry){const b=document.createElement('button');b.className='text-btn';b.textContent='Tentar novamente';b.addEventListener('click',()=>{target.hidden=true;retry();});target.append(b);}target.hidden=false;clearTimeout(setToast.timer);if(!retry)setToast.timer=setTimeout(()=>target.hidden=true,5000);}
class ApiError extends Error{constructor(message,status,details){super(message);this.status=status;this.details=details;}}
async function api(path,method='GET',data){const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),20000);try{const response=await fetch(path,{method,credentials:'same-origin',headers:{'Accept':'application/json',...(method!=='GET'?{'Content-Type':'application/json','X-CSRFToken':ui.session?.csrf_token||''}:{})},body:data===undefined?undefined:JSON.stringify(data),signal:controller.signal,cache:'no-store'});let body;try{body=await response.json();}catch{throw new ApiError('O servidor não retornou uma resposta válida. Tente novamente.',response.status);}if(!response.ok){const raw=body.error||body.message||'Não foi possível concluir esta operação.';const detail=typeof raw==='object'?(raw.message||JSON.stringify(raw)):raw;throw new ApiError(detail,response.status,body);}return body;}catch(e){if(e.name==='AbortError')throw new ApiError('A conexão demorou mais que o esperado. A operação pode ter sido salva; tente novamente para conferir.',0);if(e instanceof ApiError)throw e;throw new ApiError('Não foi possível conectar ao servidor. Confira sua conexão e tente novamente.',0);}finally{clearTimeout(timer);}}
async function session(){const priorUser=ui.session?.user?.id;ui.session=await api('/api/session');if(priorUser!==ui.session?.user?.id){ui.technicalUsers=null;ui.technicalNextOffset=null;}if(!technicalAdmin()){ui.technicalUsers=null;ui.technicalNextOffset=null;if(ui.page==='user-admin')ui.page='home';}if(ui.session.user){const spaces=ui.session.spaces||[];if(!spaces.some(s=>s.id===ui.spaceId))ui.spaceId=spaces[0]?.id||null;if(ui.spaceId)await loadState(false);else ui.state=null;}else{ui.state=null;ui.spaceId=null;}render();}
async function loadState(draw=true){if(!ui.spaceId)return;ui.state=await api(`/api/spaces/${encodeURIComponent(ui.spaceId)}/state?months=${ui.months}&start=${encodeURIComponent(ui.month<CURRENT_MONTH?CURRENT_MONTH:ui.month)}&report_month=${encodeURIComponent(ui.month)}`);if(draw)render();}
async function mutate(action,data,requestId=crypto.randomUUID(),expectedRevision=ui.state.revision){if(!writable()&&!['simulation','entry.preview','payment.preview'].includes(action))throw Error('Seu acesso permite somente consulta.');const payload={action,data,expected_revision:expectedRevision,request_id:requestId};try{const response=await api(`/api/spaces/${ui.spaceId}/actions`,'POST',payload);if(['simulation','entry.preview','payment.preview'].includes(action))return response.result;await loadState(false);return response.result;}catch(e){e.retry=()=>runMutation(action,data,requestId);if(e.status===409){await loadState(false);render();throw new ApiError('Este espaço foi atualizado em outro acesso. Os dados foram recarregados; confira os valores e repita a operação.',409);}throw e;}}
async function runMutation(action,data,requestId){try{const result=await mutate(action,data,requestId);modal.close();render();setToast('Alteração salva no espaço financeiro.');return result;}catch(e){setToast(e.message,e.status===0?e.retry:null);}}
function errorText(e){if(e.status===401&&ui.session?.user){ui.session.user=null;ui.state=null;renderAuth();}return e.message||'Não foi possível salvar. Confira os campos e tente novamente.';}
function render(){if(!ui.session?.user)return renderAuth();renderShell();}
function renderAuth(){
  ui.technicalUsers=null;ui.technicalNextOffset=null;
  const mode=ui.session?.registration_mode||'open';
  const register=ui.authMode==='register'&&mode!=='closed';
  if(!register)ui.authMode='login';
  const approval=mode==='approval';
  app.innerHTML=`<div class="auth"><section class="auth-visual"><a class="brand" href="/" aria-label="Organiza, início"><span class="brand-mark">o<span>·</span></span><span class="brand-name">organiza<span>.</span></span></a><div class="auth-story"><span class="eyebrow">MAIS CLAREZA. MAIS TRANQUILIDADE.</span><h1>Seu dinheiro no presente.<br>Seus planos no <span>futuro.</span></h1><p>Um espaço para entender suas contas, cuidar dos compromissos e escolher seus próximos passos.</p><div class="auth-points"><span>${icon('check')}Individual ou em família</span><span>${icon('check')}Tudo em um só lugar</span></div></div><div class="auth-bottom">ORGANIZAÇÃO FINANCEIRA &nbsp; / &nbsp; VERSÃO 01</div><div class="auth-orbit" aria-hidden="true"></div></section><main id="main" class="auth-side"><form class="auth-form" id="auth-form"><span class="eyebrow">SEU ESPAÇO FINANCEIRO</span><h2>${register?approval?'Solicite seu acesso.':'Comece com mais clareza.':'Bom ter você por aqui.'}</h2><p>${register?approval?'A administração técnica precisa aprovar seu cadastro antes do primeiro login.':'Crie seu acesso pessoal e organize seu primeiro espaço.':'Entre para acompanhar sua vida financeira.'}</p><div class="form-error" id="auth-error" role="alert"></div><div class="notice auth-feedback" id="auth-feedback" role="status" hidden></div>${register?field('display_name','Como podemos chamar você?','text',{autocomplete:'name',required:true,placeholder:'Seu nome'}):''}${field('username','Nome de usuário','text',{autocomplete:'username',required:true,placeholder:'seu.usuario',maxlength:64})}${field('password','Senha','password',{autocomplete:register?'new-password':'current-password',required:true,minlength:register?10:undefined,placeholder:register?'Pelo menos 10 caracteres':'Sua senha'})}${register?'<p class="form-note">Use uma senha exclusiva, com letras e números. Cada participante deve ter seu próprio acesso.</p>':''}<button class="btn btn-primary" type="submit">${register?approval?'Solicitar acesso':'Criar meu acesso':'Entrar no meu espaço'}${icon('chevron')}</button>${mode!=='closed'?`<div class="auth-switch">${register?'Já tem uma conta?':'Primeira vez por aqui?'} <button type="button" data-action="auth-toggle">${register?'Entrar':approval?'Solicitar acesso':'Criar meu acesso'}</button></div>`:'<p class="form-note section-gap">O cadastro público está fechado para este piloto. Solicite seu acesso à administração técnica.</p>'}<div class="auth-privacy">${icon('shield')}<span>Seus dados pertencem aos seus espaços. O acesso compartilhado acontece apenas com participantes autorizados.</span></div></form></main></div>`;
  bindActions();
  $('#auth-form').addEventListener('submit',async e=>{
    e.preventDefault();const form=e.currentTarget;const submit=$('button[type=submit]',form);
    if(form.dataset.pending)return;
    submit.disabled=true;$('#auth-error').textContent='';$('#auth-feedback').hidden=true;
    try{
      const data=Object.fromEntries(new FormData(form));
      const result=await api(register?'/api/auth/register':'/api/auth/login','POST',data);
      if(result.registration_pending){
        form.dataset.pending='true';$('#auth-feedback').hidden=false;$('#auth-feedback').textContent=result.message;
        submit.textContent='Solicitação enviada';return;
      }
      await session();
    }catch(err){$('#auth-error').textContent=errorText(err);}
    finally{submit.disabled=Boolean(form.dataset.pending);}
  });
}
function renderShell(){const user=ui.session.user;const spaces=ui.session.spaces||[];const current=spaces.find(s=>s.id===ui.spaceId);const page=ui.page==='user-admin'&&technicalAdmin()?['user-admin','shield','Contas de usuário']:NAV.find(x=>x[0]===ui.page)||NAV[0];app.innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar" aria-label="Menu principal"><a href="/" class="brand"><span class="brand-mark">o<span>•</span></span><span class="brand-name">organiza<span>.</span></span></a><div class="sidebar-label">SEU FINANCEIRO</div><nav class="nav">${NAV.map(([id,ico,text])=>`<button class="nav-item${ui.page===id?' active':''}" data-page="${id}"${ui.page===id?' aria-current="page"':''}>${icon(ico)}${text}</button>`).join('')}${technicalAdmin()?`<button class="nav-item${ui.page==='user-admin'?' active':''}" data-page="user-admin"${ui.page==='user-admin'?' aria-current="page"':''}>${icon('shield')}Contas de usuário</button>`:''}</nav><div class="sidebar-note">${icon('leaf')}<p>Pequenas escolhas hoje.<br><b>Mais possibilidades amanhã.</b></p></div><div class="profile"><div class="avatar">${esc(initial(user.display_name||user.username))}</div><div class="profile-copy"><b>${esc(user.display_name||user.username)}</b><small>${current?({admin:'Administrador',collaborator:'Colaborador',reader:'Somente leitura'}[current.role]||'Participante'):'Seu acesso pessoal'}</small></div><button class="icon-btn" data-action="logout" aria-label="Sair do aplicativo">${icon('logout')}</button></div></aside><div class="main-shell"><header class="topbar"><div class="space-control"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Abrir menu" aria-expanded="false">${icon('menu')}</button><span class="space-symbol">${icon('users')}</span><label class="sr-only" for="space-select">Espaço financeiro</label><select id="space-select" class="space-select">${spaces.length?spaces.map(s=>option(s.id,s.name,ui.spaceId)).join(''):option('','Seu primeiro espaço')}${option('__new','+ Novo espaço')}</select></div><div class="topbar-right"><span class="connection"><i class="status-dot"></i>Dados do seu espaço</span><span class="topbar-separator"></span><label class="sr-only" for="month-select">Mês de referência</label><input class="date-control" type="month" id="month-select" value="${ui.month}" aria-label="Mês de referência"><button class="icon-btn" data-action="refresh" aria-label="Atualizar dados">${icon('refresh')}</button></div></header><main id="main" class="main-content" tabindex="-1">${ui.page==='user-admin'?technicalUsersPage():ui.spaceId?(ui.state?renderPage(page):'<div class="boot">Carregando seu espaço…</div>'):renderWelcome()}<footer class="footer-note"><span>ORGANIZA &nbsp;·&nbsp; SUAS FINANÇAS COM CLAREZA</span><span>Valores em reais · ${esc(monthLabel(ui.month,true))} · Dados confirmados no servidor</span></footer></main></div></div>`;bindActions();$('#space-select').addEventListener('change',async e=>{if(e.target.value==='__new'){e.target.value=ui.spaceId||'';return showSpaceForm();}ui.spaceId=e.target.value;ui.simulation=null;try{await loadState();}catch(err){setToast(errorText(err));}});$('#month-select').addEventListener('change',async e=>{if(!/^\d{4}-\d{2}$/.test(e.target.value))return;ui.month=e.target.value;ui.simulation=null;try{await loadState();}catch(err){setToast(errorText(err));}});}
function renderWelcome(){return `<section class="welcome"><div class="welcome-icon">${icon('leaf')}</div><span class="eyebrow">UM COMEÇO ORGANIZADO</span><h1 style="margin-top:12px">Seu futuro começa com um espaço.</h1><p>Reúna contas, cartões e planos em um espaço financeiro. Você pode cuidar dele individualmente ou convidar pessoas da sua família.</p>${button('new-space','Criar meu primeiro espaço','plus')}<div class="welcome-options"><div class="welcome-option">${icon('wallet')}<b>Pessoal</b><small>Sua organização, no seu ritmo.</small></div><div class="welcome-option">${icon('users')}<b>Em casal</b><small>Uma visão compartilhada dos planos.</small></div><div class="welcome-option">${icon('home')}<b>Em família</b><small>Todos com seu próprio acesso.</small></div></div><small>Você escolhe quem participa. Um espaço não dá acesso aos demais.</small></section>`;}
function heading(title,description,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></div>`;}
function renderPage(){switch(ui.page){case'entries':return entriesPage();case'due':return duePage();case'cards':return cardsPage();case'debts':return debtsPage();case'future':return futurePage();case'categories':return categoriesPage();case'reports':return reportsPage();case'settings':return settingsPage();default:return homePage();}}
function metric(title,value,foot,ico,featured=false){return `<section class="metric${featured?' featured':''}" aria-label="${esc(title)}"><div class="metric-head"><span>${esc(title)}</span>${icon(ico)}</div><div class="metric-value">${esc(money(value))}</div><p class="metric-foot">${featured?'<span class="dot"></span>':''}${esc(foot)}</p></section>`;}
function monthObligations(){return list('obligations').filter(o=>o.due_date?.startsWith(ui.month)&&o.status!=='cancelled');}
function setupSteps(){if(!writable())return '';if(list('accounts').length&&list('entries').length)return '';return `<div class="setup-steps"><div class="setup-step done"><span class="step-number">${icon('check')}</span><div><b>Seu espaço está pronto</b><small>Um lugar para suas finanças</small></div></div><div class="setup-step${list('accounts').length?' done':''}"><span class="step-number">${list('accounts').length?icon('check'):'2'}</span><button data-action="new-account"><b>Cadastre uma conta</b><small>Comece pelo saldo de hoje</small></button></div><div class="setup-step"><span class="step-number">3</span><button data-action="new-entry"><b>Faça seu primeiro registro</b><small>Uma receita ou um gasto</small></button></div></div>`;}
function homePage(){const state=ui.state;const name=(ui.session.user.display_name||ui.session.user.username).split(' ')[0];const obligations=list('obligations').filter(o=>o.remaining_cents>0&&o.kind==='expense').sort((a,b)=>a.due_date.localeCompare(b.due_date)).slice(0,4);const reports=state.reports||{};const a=writable()?`${button('pix-entry','Registrar Pix','pix','soft')}${button('new-entry','Novo registro')}`:'';return `${heading(`Olá, ${esc(name)} <span style="font-size:22px" aria-hidden="true">☀</span>`,'Um olhar tranquilo para o seu dinheiro e para o que vem pela frente.',a)}${setupSteps()}<div class="summary-grid">${metric('Saldo disponível',state.balance_cents,'Dinheiro confirmado nas suas contas','wallet',true)}${metric('A receber',state.income_pending_cents,'Receitas previstas ainda não recebidas','arrowdown')}${metric('Compromisso do mês atual',state.month_commitment_cents,monthLabel(CURRENT_MONTH,true)+' · inclui atrasos','calendar')}${metric('Saldo devedor total',state.debt_cents,'Obrigações ainda não liquidadas','layers')}</div><div class="dashboard-grid"><section class="panel chart-panel"><div class="panel-head"><div><h2>Seu dinheiro, mais adiante</h2><p>Saldo projetado e compromissos nos próximos meses</p></div><button class="text-btn" data-page="future">Ver futuro ${icon('chevron')}</button></div>${projectionChart((state.projection||[]).slice(0,6))}<div class="chart-legend"><span><i class="legend-dot forest"></i>Saldo projetado</span><span><i class="legend-dot lime"></i>Compromissos</span></div></section><section class="panel"><div class="panel-head"><div><h2>No seu calendário</h2><p>Próximos pagamentos pendentes</p></div><button class="text-btn" data-page="due">Ver todos ${icon('chevron')}</button></div><div class="upcoming-list">${obligations.length?obligations.map(upcomingItem).join(''):empty('Seu calendário está livre','Registre despesas previstas para acompanhar os próximos vencimentos.','','','calendar',true)}</div></section></div><div class="grid-2"><section class="panel"><div class="panel-head"><div><h2>Onde seu dinheiro está</h2><p>Saldo realizado por conta</p></div>${writable()?'<button class="text-btn" data-action="new-account">'+icon('plus')+'Conta</button>':''}</div><div class="accounts-row">${list('accounts').length?list('accounts').map(a=>`<div class="account-tile">${icon('bank')}<b>${esc(a.name)}</b><small>${esc(a.institution||'Conta / carteira')}</small><strong>${money(a.balance_cents)}</strong></div>`).join(''):empty('Cada conta no seu lugar','Cadastre sua conta bancária ou carteira e informe o saldo inicial.','new-account','Adicionar conta','wallet',true)}</div></section><section class="panel"><div class="panel-head"><div><h2>Com o que você gastou</h2><p>Por categoria · base de compra</p></div><button class="text-btn" data-page="reports">Relatórios ${icon('chevron')}</button></div>${allocation(reports.by_category||[])}</section></div>${alertsBanner()}<div class="hint-banner">${icon('leaf')}<div><b>Clareza hoje. Espaço para os seus planos amanhã.</b><p>A projeção reúne os registros e recorrências conhecidos. Novos gastos e receitas podem mudar o caminho.</p></div><button class="text-btn" data-page="future">Explorar meu futuro ${icon('chevron')}</button></div>`;}
function upcomingItem(o){return `<div class="upcoming-item"><div class="date-tile"><b>${esc(o.due_date?.slice(8)||'—')}</b><span>${esc(monthLabel(o.due_date?.slice(0,7)))}</span></div><div class="item-body"><b>${esc(o.description||'Compromisso')}</b><small>${o.card_id?esc(label('cards',o.card_id)):esc(label('categories',o.category_id))}${o.total_installments>1?` · ${o.installment}/${o.total_installments}`:''}</small></div><div class="item-money">${money(o.remaining_cents)}${o.status==='overdue'?'<br><span class="tag tag-red">Em atraso</span>':''}</div></div>`;}
function alertsBanner(){const alerts=list('alerts');return alerts.length?`<div class="notice section-gap">${icon('bell')}<div><b>${alerts.length} ponto${alerts.length>1?'s':''} de atenção no seu espaço</b><br>${alerts.slice(0,3).map(a=>esc(a.message)).join('<br>')}</div></div>`:'';}
const COLORS=['#315d45','#a6be72','#d8d7a1','#87a89c','#ddd0b8','#a5bac7','#b8a6bd'];
function allocation(categories){const rows=categories.filter(x=>x.amount_cents>0);const total=sum(rows);if(!total)return empty('Seus gastos vão aparecer aqui','As despesas serão agrupadas pela categoria, independentemente da forma de pagamento.','','','grid',true);let used=0;const gradient=rows.map((row,i)=>{const from=used;used+=row.amount_cents/total*100;return `${COLORS[i%COLORS.length]} ${from}% ${used}%`;}).join(',');return `<div class="allocation"><div class="donut" style="background:conic-gradient(${gradient})"><div class="donut-label"><small>Total</small><b>${money(total)}</b></div></div><div class="category-legend">${rows.slice(0,5).map((row,i)=>`<div class="category-row"><span class="swatch" style="background:${COLORS[i%COLORS.length]}"></span><span>${esc(row.label||label('categories',row.id))}</span><b>${money(row.amount_cents)}</b></div>`).join('')}${rows.length>5?'<small>Outras categorias no relatório completo</small>':''}</div></div>`;}
function projectionChart(rows, simulationRows){const w=620,h=200,left=58,right=12,top=12,bottom=33;const values=rows.flatMap(r=>[r.projected_balance_cents||0,r.commitment_cents||0]);if(simulationRows)values.push(...simulationRows.map(r=>r.projected_balance_cents||0));const max=Math.max(...values,10000),min=Math.min(...values,0),range=max-min||1;const px=(i)=>left+i*((w-left-right)/Math.max(rows.length-1,1));const py=(v)=>top+(max-v)/range*(h-top-bottom);const line=(key,source=rows)=>source.map((r,i)=>`${i?'L':'M'}${px(i)},${py(r[key]||0)}`).join(' ');const yGrid=[0,.5,1].map(frac=>{const val=Math.round(max-frac*range);const y=py(val);return `<line x1="${left}" y1="${y}" x2="${w-right}" y2="${y}" stroke="#eaf0e3" stroke-dasharray="3 5"/><text x="${left-8}" y="${y+3}" text-anchor="end" font-size="9" fill="#8c9885">${esc(Math.abs(val)>=100000?Math.round(val/100000)+' mil':money(val))}</text>`;}).join('');const active=rows.some(r=>r.commitment_cents||r.income_cents||r.projected_balance_cents);return `<div class="chart-wrap"><svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img" aria-label="Projeção do saldo e dos compromissos. Valores detalhados na tela Futuro financeiro.">${yGrid}${rows.length?`<path d="${line('projected_balance_cents')}" fill="none" stroke="#315d45" stroke-width="2.5"/><path d="${line('commitment_cents')}" fill="none" stroke="#afca70" stroke-width="2" stroke-dasharray="5 4"/>${simulationRows?`<path d="${line('projected_balance_cents',simulationRows)}" fill="none" stroke="#5f89a0" stroke-width="2.5" stroke-dasharray="4 3"/>`:''}${rows.map((r,i)=>`<circle cx="${px(i)}" cy="${py(r.projected_balance_cents||0)}" r="3" fill="#315d45"/><text x="${px(i)}" y="${h-6}" text-anchor="middle" font-size="10" fill="#87917e">${esc(monthLabel(r.month))}</text>`).join('')}`:''}</svg>${active?'':`<div class="chart-empty"><span>Seu planejamento começa pelos primeiros registros.</span></div>`}</div>`;}
function entriesPage(){const selected=list('entries').filter(e=>e.competence_date?.startsWith(ui.month)||e.purchase_date?.startsWith(ui.month));const rows=selected.filter(e=>(ui.filter==='all'||(ui.filter==='pix'?e.method==='pix':e.kind===ui.filter))&&`${e.description} ${e.merchant||''} ${label('categories',e.category_id)}`.toLocaleLowerCase().includes(ui.search.toLocaleLowerCase())).sort((a,b)=>(b.purchase_date||'').localeCompare(a.purchase_date||''));return `${heading('Movimentações','Cada registro conta uma parte da sua vida financeira.',writable()?button('new-entry','Novo registro'):'')}<section class="panel"><div class="filterbar"><div class="segmented" aria-label="Filtrar movimentações">${[['all','Todas'],['income','Receitas'],['expense','Despesas'],['transfer','Transferências'],['pix','Pix']].map(([id,t])=>`<button data-filter="${id}" class="${ui.filter===id?'active':''}">${t}</button>`).join('')}</div><div class="search">${icon('search')}<input id="search-entries" class="control" placeholder="Buscar descrição ou local" aria-label="Buscar movimentações" value="${esc(ui.search)}"></div></div>${rows.length?`<div class="table-scroll"><table><thead><tr><th>Movimentação</th><th>Data</th><th>Categoria</th><th>Forma / conta</th><th>Valor total</th><th>Situação</th><th>Detalhes</th></tr></thead><tbody>${rows.map(e=>`<tr><td><div class="table-description"><span class="entry-symbol">${icon(e.kind==='income'?'arrowdown':e.kind==='transfer'?'arrows':e.method==='pix'?'pix':'arrowup')}</span><div><b>${esc(e.description)}</b><small>${esc(e.merchant||person(e.person_id))}</small></div></div></td><td>${date(e.purchase_date||e.competence_date)}</td><td>${esc(label('categories',e.category_id))}</td><td>${esc(entryMethodLabel(e))}<small>${esc(e.card_id?label('cards',e.card_id):label('accounts',e.account_id))}</small></td><td class="${e.kind==='income'?'money-in':'money-out'}">${e.kind==='income'?'+ ':e.kind==='transfer'?'':'− '}${money(e.amount_cents)}${e.installments>1?`<small>${e.installments} parcelas</small>`:''}</td><td>${settlementBadge({...e,payment_status:entryStatus(e)})}</td><td><button class="text-btn" data-action="entry-detail" data-id="${esc(e.id)}">Abrir ${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div><p class="list-footer">${rows.length} registro${rows.length>1?'s':''} no período · Pix é uma forma de pagamento, sem duplicação de registros.</p>`:empty('Um novo registro, mais clareza','Registre receitas, despesas e transferências. Seus dados ficam salvos neste espaço.','new-entry','Adicionar registro','arrows')}</section>`;}
function methodLabel(m){return ({pix:'Pix',credit:'Crédito',debit:'Débito',cash:'Dinheiro',transfer:'Transferência'}[m]||m||'—');}
function entryMethodLabel(entry){return entry.kind==='expense'&&entry.method==='transfer'&&entry.installments>1?'Parcelamento fora do cartão':methodLabel(entry.method);}

function settlementBadge(item){
  if(item.status==='cancelled')return badge('cancelled');
  const pending=item.remaining_cents??item.pending_cents;
  const status=item.payment_status||(pending===0?'paid':item.paid_cents>0?'partial':'pending');
  if(item.kind==='income'&&status==='paid')return badge('received');
  if(item.kind==='income'&&status==='partial')return '<span class="tag tag-blue">Parcialmente recebido</span>';
  return badge(status);
}
function overdueNote(item){return (item.is_overdue??(item.remaining_cents>0&&item.due_date<TODAY))?'<span class="tag tag-red">Em atraso</span>':'';}
function obligationValues(item){
  const original=item.original_amount_cents??item.amount_cents;
  const adjustment=item.amount_cents-original;
  return `<span>${item.original_amount_cents===undefined?'Valor atual':'Original'}: <b>${money(original)}</b></span>${adjustment?`<small>Ajustes: ${adjustment>0?'+ ':''}${money(adjustment)}</small>`:''}<small>Valor liquidado: ${money(item.paid_cents||0)}</small><small><b>Saldo: ${money(item.remaining_cents)}</b></small>`;
}
function paymentActions(item){
  if(!writable()||item.status==='cancelled'||!item.remaining_cents)return '';
  const invoice=Boolean(item.card_id), id=invoice?item.invoice_id:item.id;
  if(!id)return '';
  const action=invoice?'pay-invoice':'pay-obligation';
  const text=item.kind==='income'?'Confirmar recebimento':invoice?'Pagar fatura':'Confirmar pagamento';
  const future=item.kind==='expense'&&item.due_date?.slice(0,7)>CURRENT_MONTH;
  return `<div class="payment-actions"><button type="button" class="btn btn-soft btn-small" data-action="${action}" data-id="${esc(id)}">${text}</button>${future?`<button type="button" class="text-btn" data-action="${invoice?'advance-invoice':'advance-obligation'}" data-id="${esc(id)}">Antecipar pagamento</button>`:''}</div>`;
}

function duePage(){
  const rows=list('obligations').filter(o=>o.status!=='cancelled'&&(o.due_date?.startsWith(ui.month)||(o.remaining_cents>0&&o.due_date<TODAY))).sort((a,b)=>a.due_date.localeCompare(b.due_date));
  return `${heading('A pagar e a receber','Vencimento é previsão. Pagamento é uma confirmação.',writable()?button('new-entry','Novo registro'):'')}<div class="summary-grid" style="grid-template-columns:repeat(3,1fr)">${metric('Pagamentos pendentes',sum(rows.filter(o=>o.kind==='expense'),'remaining_cents'),'No mês selecionado e em atraso','calendar')}${metric('Recebimentos pendentes',sum(rows.filter(o=>o.kind==='income'),'remaining_cents'),'Entradas a confirmar','arrowdown')}${metric('Em atraso',sum(rows.filter(o=>(o.is_overdue??o.status==='overdue')&&o.kind==='expense'),'remaining_cents'),'Continuam pendentes até a confirmação','clock')}</div><section class="panel"><div class="panel-head"><div><h2>Seu calendário financeiro</h2><p>Inclui pendências vencidas de meses anteriores</p></div><span class="tag">${esc(monthLabel(ui.month,true))}</span></div>${rows.length?`<div class="table-scroll"><table><thead><tr><th>Vencimento</th><th>Descrição</th><th>Tipo</th><th>Valores da parcela</th><th>Situação</th><th>Confirmação</th></tr></thead><tbody>${rows.map(o=>`<tr data-obligation-id="${esc(o.id)}"><td>${date(o.due_date)}</td><td><b>${esc(o.description)}</b><small>${o.card_id?esc(label('cards',o.card_id)):esc(o.merchant||label('categories',o.category_id))}${o.total_installments>1?` · ${o.installment}/${o.total_installments}`:''}</small></td><td>${o.kind==='income'?'A receber':o.card_id?'Parcela do cartão':'A pagar'}</td><td class="${o.kind==='income'?'money-in':''}">${obligationValues(o)}</td><td><div class="badges">${settlementBadge(o)}${overdueNote(o)}</div></td><td>${paymentActions(o)||'—'}</td></tr>`).join('')}</tbody></table></div>`:empty('Tudo em dia por aqui','Seus vencimentos e receitas previstas aparecerão neste calendário.','','','calendar')}</section>`;
}
function cardsPage(){const cards=list('cards');const invoices=list('invoices').filter(i=>i.month>=ui.month||i.remaining_cents>0).sort((a,b)=>a.due_date.localeCompare(b.due_date));return `${heading('Cartões e faturas','Uma visão de cada cartão e dos compromissos que vêm com ele.',writable()?button('new-card','Adicionar cartão'):'')}${cards.length?`<div class="grid-3">${cards.map(c=>`<div><section class="credit-card"><div class="card-top"><div><h3>${esc(c.name)}</h3><small style="color:#c1d3bd">${esc(c.institution||'Cartão de crédito')}</small></div>${icon('card')}</div><div class="card-digits">•••• &nbsp; •••• &nbsp; ${esc(c.last_four||'••••')}</div><div class="card-bottom"><div>Compromisso futuro<strong>${money(c.committed_cents)}</strong></div><div>Fecha dia ${esc(c.closing_day)}<br>Vence dia ${esc(c.due_day)}</div></div></section><p class="card-note">Disponível estimado: <b>${money(c.available_cents)}</b> · Limite: ${money(c.limit_cents)} ${writable()?`<button class="text-btn" data-action="edit-card" data-id="${esc(c.id)}">Editar cartão</button>`:''}</p></div>`).join('')}</div><div class="notice section-gap">${icon('info')}<span>Limite estimado = limite informado menos obrigações pendentes do cartão. Ele não compõe seu saldo em dinheiro. O banco pode aplicar critérios diferentes.</span></div>`:''}<section class="panel section-gap"><div class="panel-head"><div><h2>Faturas em perspectiva</h2><p>Compras classificadas uma vez. Pagamento da fatura movimenta o caixa.</p></div></div>${invoices.length?`<div class="table-scroll"><table><thead><tr><th>Cartão / fatura</th><th>Fechamento</th><th>Vencimento</th><th>Total</th><th>Pendente</th><th>Situação</th><th>Ações</th></tr></thead><tbody>${invoices.map(i=>`<tr><td><b>${esc(label('cards',i.card_id))}</b><small>${esc(monthLabel(i.month,true))}</small></td><td>${date(i.closing_date)}</td><td>${date(i.due_date)}</td><td>Original: ${money(i.original_amount_cents??i.amount_cents)}${i.adjustment_cents?`<small>Ajustes: ${i.adjustment_cents>0?"+ ":""}${money(i.adjustment_cents)}</small>`:""}<small>Valor liquidado: ${money(i.paid_cents||0)}</small></td><td><b>${money(i.remaining_cents)}</b></td><td><div class="badges">${settlementBadge(i)}${overdueNote(i)}</div></td><td><button class="text-btn" data-action="invoice-detail" data-id="${esc(i.id)}">Ver fatura ${icon('chevron')}</button>${i.remaining_cents>0&&writable()?`<button class="btn btn-soft btn-small" data-action="pay-invoice" data-id="${esc(i.id)}">Pagar</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('Seus cartões, organizados','Cadastre um cartão para acompanhar suas compras, parcelas e faturas.','new-card','Cadastrar cartão','card')}</section>`;}
function debtsPage(){
  const rows=list('entries').filter(e=>e.kind==='expense'&&e.installments>1&&e.status!=='cancelled');
  return `${heading('Parcelamentos e dívidas','Saiba o que falta, quando termina e quanto pode ser liberado.',writable()?button('installment-entry','Nova conta parcelada'):'')}<div class="notice">${icon('info')}<span>O saldo devedor reúne obrigações ainda não liquidadas. O compromisso mensal reúne as parcelas de um mês. Datas passadas ou o término previsto nunca confirmam quitação.</span></div><section class="panel"><div class="panel-head"><div><h2>Seus parcelamentos</h2><p>${rows.length} compra${rows.length!==1?'s':''} registrada${rows.length!==1?'s':''} · saldo pendente consolidado: ${money(sum(rows,'debt_cents'))}</p></div></div>${rows.length?rows.map(e=>{
    const obs=list('obligations').filter(o=>o.entry_id===e.id&&o.status!=='cancelled');
    const paid=obs.filter(o=>!o.remaining_cents).length, total=e.installments||obs.length;
    const next=obs.filter(o=>o.remaining_cents>0).sort((a,b)=>a.due_date.localeCompare(b.due_date)||a.installment-b.installment)[0];
    const adjustment=(e.adjusted_amount_cents??e.amount_cents)-e.amount_cents;
    return `<article class="debt-item" data-entry-id="${esc(e.id)}"><div class="debt-title"><div><h3>${esc(e.description)}</h3><small>${esc(e.merchant||'Estabelecimento não informado')} · ${esc(e.card_id?label('cards',e.card_id):'Fora do cartão')}</small></div><div style="text-align:right"><div class="item-money">${money(e.debt_cents)}</div><small>saldo pendente</small></div></div><div class="progress-track" role="progressbar" aria-label="Parcelas pagas de ${esc(e.description)}" aria-valuenow="${paid}" aria-valuemax="${total}" aria-valuemin="0"><div class="progress-fill" style="width:${total?paid/total*100:0}%"></div></div><div class="debt-details"><div>Progresso<b>${paid} de ${total} parcelas pagas</b></div><div>Valor original<b>${money(e.amount_cents)}</b></div><div>Valor liquidado<b>${money(e.paid_cents||0)}</b></div>${adjustment?`<div>Ajustes<b>${adjustment>0?'+ ':''}${money(adjustment)}</b></div>`:''}<div>Saldo devedor<b>${money(e.debt_cents)}</b></div><div>Próximo vencimento<b>${date(e.next_due_date)}</b></div><div>Última parcela prevista<b>${date(e.last_due_date)}</b></div></div><div class="debt-actions">${next?paymentActions(next):settlementBadge(e)}<button class="text-btn" data-action="entry-detail" data-id="${esc(e.id)}">Detalhes ${icon('chevron')}</button></div></article>`;
  }).join(''):empty('Planos com começo, meio e fim','Cadastre suas compras parceladas, inclusive dívidas iniciadas antes de usar o aplicativo.','installment-entry','Adicionar parcelamento','layers')}</section>`;
}
function futurePage(){const rows=list('projection');const simulation=ui.simulation;return `${heading('Futuro financeiro','Enxergue os próximos meses e dê espaço aos seus planos.',button('simulate','Simular uma compra','plus','soft'))}<div class="notice">${icon('info')}<span>Projeção baseada nos lançamentos conhecidos e nas recorrências configuradas. Considera o saldo realizado de hoje e as pendências por vencimento, incluindo atrasos. Não presume ausência de novos gastos, juros desconhecidos ou futuras receitas não registradas.</span></div><section class="panel chart-panel"><div class="panel-head"><div><h2>O caminho dos seus próximos meses</h2><p>Saldo projetado e compromissos · ${ui.months} meses a partir de ${esc(monthLabel(ui.month<CURRENT_MONTH?CURRENT_MONTH:ui.month,true))}</p></div><label><span class="sr-only">Horizonte da projeção</span><select id="projection-months" class="control" style="width:105px;min-height:33px;font-size:10px">${[12,18,24,36,60].map(n=>option(n,`${n} meses`,ui.months)).join('')}</select></label></div>${projectionChart(rows,simulation?.projection)}<div class="chart-legend"><span><i class="legend-dot forest"></i>Saldo projetado</span><span><i class="legend-dot lime"></i>Compromissos</span>${simulation?'<span><i class="legend-dot" style="background:#5f89a0"></i>Com a compra simulada</span>':''}</div></section>${simulation?`<div class="hint-banner">${icon('chart')}<div><b>Simulação ativa · nenhuma dívida foi registrada</b><p>${esc(Array.isArray(simulation.assumptions)?simulation.assumptions.join(' '):simulation.assumptions||'Compare o cenário simulado com seus compromissos atuais.')}</p></div><button class="text-btn" data-action="clear-simulation">Limpar simulação</button></div>`:''}<section class="panel section-gap"><div class="panel-head"><div><h2>Mês a mês, com clareza</h2><p>Receitas e compromissos previstos não são dinheiro confirmado</p></div></div><div class="table-scroll"><table class="projection-table"><thead><tr><th>Mês</th><th>Receitas previstas</th><th>Compromissos</th><th>Redução das parcelas</th><th>Saldo projetado</th>${simulation?'<th>Saldo simulado</th>':''}<th>Dívidas com término previsto</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td><b>${esc(monthLabel(r.month,true))}</b></td><td class="money-in">${money(r.income_cents)}</td><td>${money(r.commitment_cents)}</td><td>${r.released_cents>0?`<span class="tag tag-green">− ${money(r.released_cents)}</span>`:'—'}</td><td class="${r.projected_balance_cents<0?'money-negative':''}"><b>${money(r.projected_balance_cents)}</b></td>${simulation?`<td class="${simulation.projection?.[i]?.projected_balance_cents<0?'money-negative':''}">${money(simulation.projection?.[i]?.projected_balance_cents)}</td>`:''}<td style="white-space:normal;min-width:160px">${r.ending_debts?.length?r.ending_debts.map(d=>esc(d.description)).join(', '):'—'}</td></tr>`).join('')}</tbody></table></div><p class="list-footer">Término previsto descreve o calendário de parcelas. A dívida só é quitada após a confirmação dos pagamentos.</p></section>`;}
function categoriesPage(){const rows=list('categories');const merchants=ui.state.reports?.by_merchant||[];return `${heading('Categorias e locais','O que você comprou, onde comprou e como pagou são coisas diferentes.',writable()?button('new-category','Nova categoria'):'')}<div class="grid-2"><section class="panel"><div class="panel-head"><div><h2>Suas categorias</h2><p>Categorias e subcategorias de receitas e despesas</p></div></div>${rows.length?`<div class="table-scroll"><table><thead><tr><th>Categoria</th><th>Grupo</th><th>Ações</th></tr></thead><tbody>${rows.map(c=>`<tr><td><b>${esc(c.name)}</b></td><td>${c.parent_id?esc(label('categories',c.parent_id)):'Categoria principal'}</td><td>${writable()?`<button class="text-btn" data-action="edit-category" data-id="${esc(c.id)}">Editar ${c.status==='archived'?'(arquivada)':''}</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('Categorias do seu jeito','Crie categorias para entender os seus hábitos.','new-category','Adicionar categoria','grid')}</section><section class="panel"><div class="panel-head"><div><h2>Seus estabelecimentos</h2><p>Identificados nos registros do período</p></div></div>${reportBars(merchants,'Os estabelecimentos aparecerão conforme você registrar seus gastos.')}<div class="notice section-gap">${icon('pix')}<span>Pix, crédito e débito são formas de pagamento. Um gasto em Alimentação continua em Alimentação, seja qual for a forma de pagar.</span></div></section></div>`;}
function reportBars(rows,emptyText){const nonzero=rows.filter(x=>x.amount_cents);if(!nonzero.length)return empty('Os dados vão contar essa história',emptyText||'Registre suas movimentações para comparar os valores do período.','','','report',true);const max=Math.max(...nonzero.map(x=>x.amount_cents),1);return nonzero.map((r,i)=>`<div class="report-bar-row"><div class="report-bar-title"><span>${esc(r.label||r.id||'Não informado')}</span><b>${money(r.amount_cents)}</b></div><div class="report-bar"><span style="width:${r.amount_cents/max*100}%;background:${COLORS[i%COLORS.length]}"></span></div></div>`).join('');}
function reportsPage(){const r=ui.state.reports_by_basis?.[ui.reportBasis]||ui.state.reports||{};const basisLabel=ui.reportBasis==='competence'?'competência':'compra';return `${heading('Relatórios e orçamento','Entenda seus hábitos e decida o que merece mais espaço.',writable()?button('new-budget','Definir orçamento','plus','soft'):'')}<div class="filterbar"><label for="report-basis" class="muted">Base dos relatórios</label><select class="control" style="width:210px" id="report-basis">${option('purchase','Data da compra',ui.reportBasis)}${option('competence','Data de competência',ui.reportBasis)}</select></div><div class="notice">${icon('info')}<span><b>Base de consumo:</b> ${basisLabel} no mês selecionado. Pagamento de fatura não é uma segunda despesa. <b>Caixa:</b> entradas e saídas confirmadas são mostradas separadamente. Transferências próprias ficam fora de receitas e despesas.</span></div><div class="summary-grid">${metric('Receitas do período',r.income_cents,'Base de '+basisLabel,'arrowdown',true)}${metric('Despesas do período',r.expense_cents,'Base de '+basisLabel,'arrowup')}${metric('Entradas no caixa',r.cash_income_cents,'Recebimentos confirmados','wallet')}${metric('Saídas do caixa',r.cash_expense_cents,'Pagamentos confirmados','arrows')}</div><div class="grid-2"><section class="panel"><div class="panel-head"><div><h2>Gastos por categoria</h2><p>Base de ${basisLabel}</p></div></div>${reportBars(r.by_category||[])}</section><section class="panel"><div class="panel-head"><div><h2>Orçamento por categoria</h2><p>Base de compra · ${esc(monthLabel(ui.month,true))}</p></div></div>${budgetView(r)}</section><section class="panel"><div class="panel-head"><div><h2>Por estabelecimento</h2><p>Onde seu dinheiro foi aplicado</p></div></div>${reportBars(r.by_merchant||[])}</section><section class="panel"><div class="panel-head"><div><h2>Por pessoa</h2><p>A quem o gasto pertence</p></div></div>${reportBars((r.by_person||[]).map(row=>({...row,label:person(row.id)})))}</section><section class="panel"><div class="panel-head"><div><h2>Por forma de pagamento</h2><p>A mesma categoria pode conter várias formas</p></div></div>${reportBars((r.by_method||[]).map(x=>({...x,label:methodLabel(x.id)})))}</section><section class="panel"><div class="panel-head"><div><h2>Por cartão</h2><p>Compras atribuídas a cada cartão</p></div></div>${reportBars(r.by_card||[])}</section><section class="panel"><div class="panel-head"><div><h2>Por subcategoria</h2><p>Um olhar mais próximo para os seus hábitos</p></div></div>${reportBars(r.by_subcategory||[])}</section></div>`;}
function budgetView(reports){const budgets=list('budgets').filter(b=>b.month===ui.month);return budgets.length?budgets.map(b=>{const actual=Number.isSafeInteger(b.spent_cents)?b.spent_cents:((reports.by_category||[]).find(x=>x.id===b.category_id)?.amount_cents||0);return `<div class="report-bar-row"><div class="report-bar-title"><span>${esc(label('categories',b.category_id))}</span><b>${money(actual)} / ${money(b.amount_cents)}</b></div><div class="report-bar"><span style="width:${Math.min(100,b.amount_cents?actual/b.amount_cents*100:100)}%;background:${actual>=b.amount_cents?'#ab7557':'#91ac62'}"></span></div><small>${actual>b.amount_cents?'Acima do orçamento em '+money(actual-b.amount_cents):'Restante: '+money(b.amount_cents-actual)}</small></div>`;}).join(''):empty('Dê um destino ao seu dinheiro','Defina quanto pretende gastar em cada categoria neste mês.','new-budget','Definir orçamento','grid',true);}
function settingsPage(){const members=list('members');return `${heading('Configurações > Participantes','Um espaço compartilhado, com acessos individuais.',button('new-space','Novo espaço','plus','soft'))}<nav class="settings-shortcuts" aria-label="Seções das configurações"><a href="#space-participants">Participantes</a><a href="#financial-accounts">Contas financeiras</a>${technicalAdmin()?'<button class="text-btn" data-page="user-admin">Contas de usuário</button>':''}</nav><div class="settings-grid"><div><section class="panel" id="space-participants"><div class="panel-head"><div><h2>${esc(ui.state.space.name)}</h2><p>Todos os participantes autorizados compartilham a visão deste espaço</p></div><span class="tag">${admin()?'Administrador':writable()?'Colaborador':'Leitor'}</span></div><div class="notice">${icon('shield')}<span>Informações privadas devem ficar em outro espaço. Participar de um espaço familiar não permite acessar os espaços pessoais dos demais.</span></div>${members.map(m=>`<div class="participant"><div class="avatar">${esc(initial(m.display_name||m.username))}</div><div class="item-body"><b>${esc(m.display_name||m.username)}</b><small>@${esc(m.username)} · ${participantIdentity(m)}</small></div>${participantStatus(m)}${admin()?`<label><span class="sr-only">Perfil de ${esc(m.username)}</span><select class="control role-change" data-id="${esc(m.id)}" data-old="${esc(m.role)}">${[['admin','Administrador'],['collaborator','Colaborador'],['reader','Leitor']].map(([k,v])=>option(k,v,m.role)).join('')}</select></label>${!ownParticipant(m)?`<button class="icon-btn" data-action="remove-member" data-id="${esc(m.id)}" aria-label="Remover ${esc(m.username)}">${icon('close')}</button>`:''}`:`<span class="tag">${esc({admin:'Administrador',collaborator:'Colaborador',reader:'Leitor'}[m.role]||m.role)}</span>`}</div>`).join('')}${admin()?`<div class="section-gap">${button('new-member','Adicionar participante','users','soft')}</div>`:''}</section><section class="panel section-gap" id="financial-accounts"><div class="panel-head"><div><h2>Contas financeiras e carteiras</h2><p>Saldos confirmados no servidor</p></div>${writable()?'<button class="text-btn" data-action="new-account">'+icon('plus')+'Adicionar</button>':''}</div>${list('accounts').length?list('accounts').map(a=>`<div class="participant"><span class="entry-symbol">${icon('bank')}</span><div class="item-body"><b>${esc(a.name)}</b><small>${esc(a.institution||'Carteira')} · Referência ${date(a.reference_date)}</small></div><b class="item-money">${money(a.balance_cents)}</b>${writable()?`<button class="text-btn" data-action="edit-account" data-id="${esc(a.id)}">Editar</button>`:''}</div>`).join(''):empty('Uma conta para começar','Informe o saldo inicial da sua conta ou carteira.','new-account','Adicionar conta','wallet',true)}</section><section class="panel section-gap"><div class="panel-head"><div><h2>Recorrências</h2><p>As ocorrências confirmadas preservam seu histórico</p></div></div>${list('recurrences').length?list('recurrences').map(r=>`<div class="participant"><div class="item-body"><b>${esc(r.description||byId('entries',r.entry_id)?.description||'Recorrência mensal')}</b><small>${r.active===false?'Encerrada':r.end_date?'Até '+date(r.end_date):'Sem término definido'}</small></div>${writable()?`<button class="text-btn" data-action="recurrence-edit" data-id="${esc(r.id)}">Alterar futuras</button>`:''}</div>`).join(''):empty('Sem recorrências configuradas','Ao registrar uma movimentação, escolha a repetição mensal quando fizer sentido.','','','refresh',true)}</section></div><div><section class="panel"><div class="panel-head"><div><h2>Atividade do espaço</h2><p>Autoria e alterações relevantes</p></div></div>${list('audit').length?list('audit').slice(0,12).map(a=>`<div class="audit-item"><b>${esc(auditLabel(a.action||a.event))}</b>${a.actor?' · '+esc(a.actor):a.username?' · '+esc(a.username):a.actor_id?' · '+esc(person(a.actor_id)):''}<time>${esc(a.created_at?new Date(a.created_at).toLocaleString('pt-BR',{timeZone:'America/Manaus'}):'Registrado no servidor')}</time></div>`).join(''):empty('O histórico começa aqui','As alterações relevantes serão registradas com autoria.','','','clock',true)}</section><section class="panel section-gap"><h2>Sobre esta versão</h2><p class="form-note" style="margin-top:13px">Organiza V01 · uso com conexão ao servidor. A instalação como aplicativo depende do navegador; não há edição financeira offline. Sem integração bancária, push ou cálculos automáticos de juros.</p><div class="detail-list"><div><dt>Persistência</dt><dd>No servidor</dd></div><div><dt>Acesso</dt><dd>Individual e autenticado</dd></div><div><dt>Sincronização</dt><dd>Dados no servidor</dd></div></div></section></div></div>`;}
function auditLabel(action){return ({'space.create':'Espaço criado','account.create':'Conta cadastrada','account.update':'Conta atualizada','card.create':'Cartão cadastrado','card.update':'Cartão atualizado','category.create':'Categoria criada','category.update':'Categoria atualizada','entry.create':'Movimentação registrada','entry.cancel':'Movimentação cancelada','payment.advance':'Pagamento antecipado confirmado','invoice.pay':'Pagamento de fatura confirmado','obligation.pay':'Pagamento ou recebimento confirmado','payment.reverse':'Confirmação estornada','obligation.adjust':'Ajuste financeiro registrado','invoice.update':'Fatura ajustada','budget.set':'Orçamento definido','recurrence.update':'Recorrência atualizada','member.add':'Participante adicionado','member.update':'Perfil de participante alterado','member.remove':'Participante removido'}[action]||'Atualização do espaço');}
function entryStatus(entry){if(entry.status==='cancelled')return 'cancelled';if(entry.kind==='transfer')return 'paid';if(entry.pending_cents===0)return entry.kind==='income'?'received':'paid';if(entry.paid_cents>0)return 'partial';if(entry.next_due_date&&entry.next_due_date<TODAY)return 'overdue';return 'pending';}
function suggestedCardDue(card,purchase){const [year,month,day]=purchase.split('-').map(Number);const days=(y,m)=>new Date(Date.UTC(y,m+1,0)).getUTCDate();let anchor=new Date(Date.UTC(year,month-1,1));if(day>Math.min(card.closing_day,days(year,month-1)))anchor.setUTCMonth(anchor.getUTCMonth()+1);if(card.due_day<=card.closing_day)anchor.setUTCMonth(anchor.getUTCMonth()+1);const dueDay=Math.min(card.due_day,days(anchor.getUTCFullYear(),anchor.getUTCMonth()));return `${anchor.getUTCFullYear()}-${String(anchor.getUTCMonth()+1).padStart(2,'0')}-${String(dueDay).padStart(2,'0')}`;}
function showOccurrenceEdit(id){const entry=byId('entries',id);showDialog('Editar esta ocorrência','A regra das próximas ocorrências permanece igual.',`<div class="form-grid">${field('description','Descrição','text',{required:true,full:true,value:entry.description,maxlength:240})}${field('amount_cents','Valor desta ocorrência (R$)','text',{required:true,inputmode:'decimal',value:moneyInput(entry.amount_cents),full:true})}</div><p class="form-note section-gap">Somente ocorrências pendentes podem ser editadas. Use o ajuste com motivo quando houver desconto ou encargo informado.</p>`,async(d,rid)=>{await mutate('recurrence.update',{recurrence_id:entry.recurrence_id,scope:'occurrence',entry_id:id,changes:{description:d.description,amount_cents:cents(d.amount_cents)}},rid);},'Salvar esta ocorrência');}
function field(name,title,type='text',attrs={}){const {options,help,full,value,...rest}=attrs;const id=`f-${name}`;const attr=Object.entries(rest).filter(([,v])=>v!==undefined&&v!==false).map(([k,v])=>v===true?esc(k):`${esc(k)}="${esc(v)}"`).join(' ');let input;if(type==='select')input=`<select class="control" id="${id}" name="${name}" ${attr}>${(options||[]).map(o=>Array.isArray(o)?option(o[0],o[1],value):option(o.id,o.name||o.label,value)).join('')}</select>`;else if(type==='textarea')input=`<textarea class="control" id="${id}" name="${name}" rows="2" ${attr}>${esc(value||'')}</textarea>`;else input=`<input class="control" id="${id}" name="${name}" type="${type}" ${value!==undefined?`value="${esc(value)}"`:''} ${attr}>`;return `<div class="field${full?' full':''}"><label for="${id}">${esc(title)}</label>${input}${help?`<small>${esc(help)}</small>`:''}</div>`;}
function check(name,title,checked=false){return `<label class="checkbox-field"><input name="${name}" id="f-${name}" type="checkbox"${checked?' checked':''}>${esc(title)}</label>`;}
function values(form){const object=Object.fromEntries(new FormData(form));$$('input[type=checkbox]',form).forEach(i=>object[i.name]=i.checked);return object;}
function entityOptions(key,emptyLabel='Selecione'){return [['',emptyLabel],...list(key).filter(x=>x.status!=='archived').map(x=>[x.id,x.name||x.description])];}
function personOptions(){return [['','Não informado'],...list('members').map(m=>[m.user_id,m.display_name||m.username])];}
function showDialog(title,description,body,onSubmit,submitLabel='Salvar',successMessage=''){modal.innerHTML=`<form id="dialog-form"><header class="modal-header"><div><h2 id="modal-title">${esc(title)}</h2><p>${esc(description)}</p></div><button type="button" class="icon-btn" data-action="close-modal" aria-label="Fechar janela">${icon('close')}</button></header><div class="modal-body"><div class="form-error" id="form-error" role="alert"></div>${body}</div><footer class="modal-footer"><button type="button" class="btn btn-soft" data-action="close-modal">${onSubmit?'Cancelar':'Fechar'}</button>${onSubmit?`<button type="submit" class="btn btn-primary">${esc(submitLabel)}</button>`:''}</footer></form>`;modal.onclick=delegate;const form=$('#dialog-form');let pendingId=crypto.randomUUID();if(onSubmit)form.addEventListener('submit',async event=>{event.preventDefault();const save=$('button[type=submit]',form);if(save.disabled)return;save.disabled=true;$('#form-error').textContent='';try{await onSubmit(values(form),pendingId);modal.close();render();setToast(successMessage||(submitLabel==='Simular cenário'?'Simulação pronta. Nenhuma dívida foi criada.':'Alteração salva no espaço financeiro.'));}catch(e){$('#form-error').textContent=errorText(e);if(e.status!==0)pendingId=crypto.randomUUID();}finally{save.disabled=false;}});if(!modal.open)modal.showModal();return form;}
function showSpaceForm(){showDialog('Seu novo espaço','Pessoal, em casal ou em família: você escolhe.',`<p class="form-note">O nome ajuda a distinguir seus contextos financeiros. Você poderá adicionar participantes depois.</p>${field('name','Nome do espaço','text',{required:true,maxlength:120,placeholder:'Ex.: Pessoal ou Nossa família'})}`,async data=>{const response=await api('/api/spaces','POST',data);ui.spaceId=response.space.id;ui.page='home';ui.simulation=null;await session();},'Criar espaço');}
function showAccountForm(){showDialog('Uma conta no seu espaço','Informe o saldo na data de referência, antes dos novos registros.',`<div class="form-grid">${field('name','Nome da conta ou carteira','text',{full:true,required:true,maxlength:120,placeholder:'Ex.: Conta principal'})}${field('institution','Instituição','text',{placeholder:'Banco, carteira ou dinheiro',maxlength:120})}${field('owner_id','Responsável','select',{options:personOptions(),value:ui.session.user.id})}${field('opening_balance_cents','Saldo inicial (R$)','text',{inputmode:'decimal',required:true,value:'0,00',help:'Pode ser negativo em uma conta devedora.'})}${field('reference_date','Data de referência','date',{required:true,value:TODAY,max:TODAY})}</div><p class="form-note section-gap">O limite do cartão é cadastrado separadamente e não entra neste saldo.</p>`,async(d,id)=>{d.opening_balance_cents=cents(d.opening_balance_cents);if(!d.owner_id)delete d.owner_id;await mutate('account.create',d,id);},'Cadastrar conta');}
function showEntityEdit(kind,id){const key={account:'accounts',card:'cards',category:'categories'}[kind];const item=byId(key,id);if(!item)throw Error('Cadastro não encontrado.');let fields=field('name',kind==='category'?'Nome da categoria':'Nome / apelido','text',{value:item.name,required:true,full:true,maxlength:120});if(kind!=='category')fields+=field('institution','Instituição','text',{value:item.institution,maxlength:120})+field(kind==='card'?'holder_id':'owner_id','Pessoa responsável','select',{value:item.holder_id||item.owner_id,options:personOptions()});if(kind==='card')fields+=field('last_four','Últimos 4 dígitos','text',{value:item.last_four||'',pattern:'[0-9]{4}',maxlength:4,inputmode:'numeric'})+field('limit_cents','Limite informado (R$)','text',{value:moneyInput(item.limit_cents),required:true,inputmode:'decimal'})+field('account_id','Conta usual de pagamento','select',{full:true,value:item.account_id,required:true,options:entityOptions('accounts')});if(kind==='category')fields+=field('parent_id','Categoria principal','select',{full:true,value:item.parent_id,options:[['','Nenhuma — categoria principal'],...list('categories').filter(c=>c.id!==id).map(c=>[c.id,c.name])]});fields+=field('status','Situação','select',{full:true,value:item.status||'active',options:[['active','Ativo'],['archived','Arquivado']]});showDialog('Editar '+({account:'conta',card:'cartão',category:'categoria'}[kind]),'O histórico financeiro é preservado.',`<div class="form-grid">${fields}</div><p class="form-note section-gap">${kind==='card'?'Ajuste datas de cartões com compras diretamente na fatura. ':''}Arquivar oculta este cadastro dos novos registros. Referências em recorrências precisam ser ajustadas antes de arquivar.</p>`,async(d,rid)=>{d[`${kind}_id`]=id;if(kind==='card')d.limit_cents=cents(d.limit_cents);for(const k of ['owner_id','holder_id'])if(d[k]==='')delete d[k];if(kind==='category'&&!d.parent_id)d.parent_id=null;await mutate(`${kind}.update`,d,rid);},'Salvar alterações');}
function showCardForm(){if(!list('accounts').length){setToast('Cadastre primeiro a conta usada para pagar o cartão.');return showAccountForm();}showDialog('Adicionar cartão','Apenas os últimos quatro dígitos são opcionais. Nunca informe senha ou CVV.',`<div class="form-grid">${field('name','Apelido do cartão','text',{full:true,required:true,maxlength:120,placeholder:'Ex.: Cartão do dia a dia'})}${field('institution','Instituição','text',{maxlength:120})}${field('holder_id','Titular','select',{options:personOptions(),value:ui.session.user.id})}${field('last_four','Últimos 4 dígitos (opcional)','text',{inputmode:'numeric',pattern:'[0-9]{4}',maxlength:4,placeholder:'1234'})}${field('limit_cents','Limite informado (R$)','text',{inputmode:'decimal',required:true,value:'0,00'})}${field('closing_day','Dia do fechamento','number',{required:true,min:1,max:31,value:10})}${field('due_day','Dia do vencimento','number',{required:true,min:1,max:31,value:20})}${field('account_id','Conta usual de pagamento','select',{full:true,required:true,options:entityOptions('accounts'),value:list('accounts')[0]?.id})}</div><p class="form-note section-gap">Dias inexistentes usam o último dia do mês. As datas podem ser ajustadas em cada fatura quando o processamento do banco variar.</p>`,async(d,id)=>{d.limit_cents=cents(d.limit_cents);d.closing_day=Number(d.closing_day);d.due_day=Number(d.due_day);if(!d.holder_id)delete d.holder_id;await mutate('card.create',d,id);},'Cadastrar cartão');}
function showEntryForm(mode='normal'){if(mode==='installment')return showInstallmentForm();if(!list('accounts').length){setToast('Comece cadastrando sua conta ou carteira.');return showAccountForm();}showDialog(mode==='pix'?'Registrar Pix':'Novo registro','Um registro simples. Cada informação no seu lugar.',`<div class="notice">${icon('layers')}<span>Uma conta ou compra em várias parcelas? <button type="button" class="text-btn" data-action="installment-entry">Cadastrar conta parcelada</button></span></div><div class="form-grid">${field('kind','Tipo de movimentação','select',{options:[['expense','Despesa'],['income','Receita'],['transfer','Transferência própria']],value:'expense'})}${field('method','Forma de pagamento','select',{options:[['pix','Pix'],['debit','Débito'],['cash','Dinheiro'],['credit','Crédito'],['transfer','Transferência']],value:'pix'})}${field('description','Descrição','text',{full:true,required:true,maxlength:240,placeholder:'Ex.: Supermercado, salário, aluguel…'})}${field('amount_cents','Valor total (R$)','text',{required:true,inputmode:'decimal',placeholder:'0,00'})}${field('category_id','Categoria / subcategoria','select',{options:entityOptions('categories','Selecione uma categoria')})}${field('merchant','Estabelecimento ou favorecido','text',{maxlength:200,placeholder:'Onde / para quem'})}${field('person_id','A quem pertence','select',{options:personOptions(),value:ui.session.user.id})}${field('account_id','Conta de origem / destino','select',{required:true,options:entityOptions('accounts'),value:list('accounts')[0]?.id})}${field('destination_account_id','Conta de destino da transferência','select',{options:entityOptions('accounts')})}${field('card_id','Cartão de crédito','select',{options:entityOptions('cards'),value:list('cards')[0]?.id})}<input name="installments" id="f-installments" type="hidden" value="1">${field('purchase_date','Data da compra / registro','date',{value:TODAY,required:true})}${field('competence_date','Data de competência','date',{value:TODAY,required:true})}${field('due_date','Primeiro vencimento / data prevista','date',{value:TODAY,required:true,full:true,help:'No crédito, orienta a primeira fatura; confira a atribuição após salvar.'})}<input name="paid_installments" id="f-paid_installments" type="hidden" value="0">${field('recurrence','Repetição','select',{options:[['','Não repetir'],['monthly','Todo mês']]})}${field('end_date','Fim da recorrência (opcional)','date',{})}<div class="field"><span class="eyebrow">CONFIRMAÇÃO</span>${check('paid','Pagamento / recebimento já confirmado',false)}</div>${field('paid_on','Data efetiva do pagamento / recebimento','date',{value:TODAY,max:TODAY})}${field('paid_by','Quem pagou / recebeu','select',{options:personOptions(),value:ui.session.user.id})}${field('channel','Canal (opcional)','select',{options:[['','Não informado'],['presencial','Presencial'],['online','Online']]})}${field('tags','Etiquetas (opcional)','text',{placeholder:'Separe por vírgulas'})}${field('notes','Observações (opcional)','textarea',{full:true,maxlength:2000})}</div><p class="form-note section-gap" id="entry-guidance">Marcar como confirmado movimenta o saldo da conta. Uma data de vencimento, sozinha, não confirma pagamento.</p>`,async(d,id)=>{d.amount_cents=cents(d.amount_cents);if(d.amount_cents<=0)throw Error('O valor total deve ser maior que zero.');d.installments=Number(d.installments);d.paid_installments=Number(d.paid_installments);d.tags=d.tags?d.tags.split(',').map(x=>x.trim()).filter(Boolean):[];if(d.kind==='transfer'){d.method=d.method==='pix'?'pix':'transfer';d.installments=1;d.paid_installments=0;d.paid=true;delete d.card_id;delete d.category_id;delete d.recurrence;delete d.end_date;}else if(d.method==='credit'){if(!d.card_id)throw Error('Selecione o cartão da compra.');d.paid=false;delete d.destination_account_id;}else{delete d.card_id;delete d.destination_account_id;}if(d.recurrence){d.recurrence={frequency:'monthly',...(d.end_date?{end_date:d.end_date}:{})};}else delete d.recurrence;delete d.end_date;if(!d.paid){delete d.paid_on;delete d.paid_by;}if(d.method==='credit')delete d.account_id;for(const key of ['person_id','category_id','merchant','notes','channel','paid_by'])if(d[key]==='')delete d[key];await mutate('entry.create',d,id);},'Salvar registro');function updateEntryFields(){const kind=$('#f-kind').value;const creditOption=$('#f-method option[value=credit]');creditOption.disabled=kind!=='expense';if(kind!=='expense'&&$('#f-method').value==='credit')$('#f-method').value='pix';const credit=kind==='expense'&&$('#f-method').value==='credit';const transfer=kind==='transfer';const recurring=$('#f-recurrence').value==='monthly';for(const [name,visible]of [['destination_account_id',transfer],['card_id',credit],['category_id',!transfer],['installments',!transfer],['paid_installments',!transfer],['recurrence',!transfer],['end_date',recurring&&!transfer],['paid_on',!credit],['paid_by',!credit],['account_id',!credit]]){const el=$(`#f-${name}`);if(el?.closest('.field')){el.closest('.field').hidden=!visible;el.required=['destination_account_id','card_id','account_id'].includes(name)&&visible;}}$('#f-paid').closest('.field').hidden=credit||transfer;$('#f-paid').disabled=credit||transfer;$('#f-method').closest('.field').hidden=transfer;$('#entry-guidance').textContent=credit?'A compra gera parcelas na fatura. Confirme a saída de dinheiro ao pagar a fatura, na tela Cartões.':transfer?'A transferência move dinheiro entre suas contas e não entra como receita ou despesa.':'Marcar como confirmado movimenta o saldo da conta. Uma data de vencimento, sozinha, não confirma pagamento.';}['kind','method','recurrence'].forEach(n=>$(`#f-${n}`).addEventListener('change',updateEntryFields));function suggestDue(){if($('#f-kind').value==='expense'&&$('#f-method').value==='credit'){const card=byId('cards',$('#f-card_id').value);if(card&&$('#f-purchase_date').value)$('#f-due_date').value=suggestedCardDue(card,$('#f-purchase_date').value);}}['kind','method','card_id','purchase_date'].forEach(n=>$(`#f-${n}`).addEventListener('change',suggestDue));updateEntryFields();suggestDue();}

function showInstallmentForm(){
  const activeCards=list('cards').filter(c=>c.status!=='archived');
  modal.innerHTML=`<form id="dialog-form" class="installment-form" novalidate>
    <header class="modal-header"><div><h2 id="modal-title">Nova conta parcelada</h2><p>Escolha a modalidade, informe os valores e confira cada parcela.</p></div><button type="button" class="icon-btn" data-action="close-modal" aria-label="Fechar janela">${icon('close')}</button></header>
    <div class="modal-body"><ol class="installment-steps" aria-label="Etapas do cadastro"><li data-step-label="1">1. Conta</li><li data-step-label="2">2. Valores</li><li data-step-label="3">3. Conferência</li></ol><div class="form-error" id="form-error" role="alert" tabindex="-1"></div>
      <fieldset id="installment-fields"><legend class="sr-only">Dados da conta parcelada</legend><section class="installment-step" data-step="1">
        <div class="form-grid">${field('description','Descrição da conta ou compra','text',{full:true,required:true,maxlength:240,placeholder:'Ex.: Geladeira, curso, acordo de dívida…'})}${field('modality','Modalidade','select',{full:true,value:'outside',options:[['outside','Parcelamento fora do cartão'],['credit','Cartão de crédito']]})}${field('card_id','Cartão da compra','select',{full:true,options:entityOptions('cards','Selecione o cartão')})}</div>
        <p id="installment-modality-help" class="form-note section-gap"></p>
        <details class="installment-details"><summary>Estabelecimento, categoria e responsável</summary><div class="form-grid">${field('merchant','Estabelecimento ou credor (opcional)','text',{maxlength:500,full:true,placeholder:'Loja, instituição ou pessoa a receber'})}${field('category_id','Categoria / subcategoria (opcional)','select',{options:entityOptions('categories','Não informar')})}${field('person_id','Responsável (opcional)','select',{options:personOptions(),value:ui.session.user.id})}</div></details>
      </section><section class="installment-step" data-step="2" hidden>
        <div class="form-grid">${field('value_mode','Qual valor você vai informar?','select',{full:true,value:'total',options:[['total','Valor total da compra ou dívida'],['installment','Valor de cada parcela igual']]})}${field('amount_cents','Valor total (R$)','text',{required:true,inputmode:'decimal',placeholder:'1.000,00',help:'O total será dividido pela quantidade de parcelas.'})}${field('installments','Quantidade de parcelas','number',{required:true,min:1,max:600,step:1,value:3})}${field('due_date','Primeiro vencimento','date',{full:true,required:true,value:TODAY,help:'Data da primeira parcela original, inclusive nas dívidas anteriores.'})}${field('first_invoice_month','Mês da primeira fatura','month',{full:true,required:true,value:CURRENT_MONTH})}${field('paid_installments','Quantas parcelas já foram pagas?','number',{full:true,required:true,value:0,min:0,max:600,step:1,help:'Informe apenas parcelas quitadas antes deste cadastro. Não serão criadas saídas antigas de dinheiro.'})}</div>
        <p id="installment-value-help" class="form-note section-gap"></p>
        <details class="installment-details"><summary>Data da compra, conta e observações (opcional)</summary><div class="form-grid">${field('purchase_date','Data da compra / registro','date',{full:true,required:true,value:TODAY})}${field('account_id','Conta prevista para pagar (opcional)','select',{full:true,options:entityOptions('accounts','Escolher ao confirmar o pagamento')})}${field('notes','Observações (opcional)','textarea',{full:true,maxlength:2000})}</div></details>
      </section><section class="installment-step" data-step="3" hidden><div id="installment-preview"></div></section></fieldset>
    </div><footer class="modal-footer"><button type="button" class="btn btn-soft" data-action="close-modal">Cancelar</button><button type="button" class="btn btn-soft" id="installment-back" hidden>Voltar</button><button type="button" class="btn btn-primary" id="installment-next">Continuar</button><button type="submit" class="btn btn-primary" id="installment-confirm" hidden>Confirmar cadastro</button></footer></form>`;
  modal.onclick=delegate;
  const form=$('#dialog-form');
  const next=$('#installment-next'), back=$('#installment-back'), confirm=$('#installment-confirm');
  let step=1, busy=false, preview=null, previewPayload=null, pendingId=null, pendingSignature=null;
  for(const input of $$('input,select,textarea',form)){
    const container=input.closest('.field');
    if(!container)continue;
    const message=document.createElement('small');message.className='field-error';message.id=`${input.id}-error`;message.setAttribute('role','alert');container.append(message);
    input.setAttribute('aria-describedby',message.id);
  }
  function fieldError(name,message){
    const input=$(`#f-${name}`,form);if(!input)return;
    input.setAttribute('aria-invalid','true');$(`#${input.id}-error`,form).textContent=message;
    const details=input.closest('details');if(details)details.open=true;
  }
  function clearErrors(){
    $('#form-error').textContent='';$$('[aria-invalid]',form).forEach(i=>i.removeAttribute('aria-invalid'));$$('.field-error',form).forEach(i=>i.textContent='');
  }
  function showStep(value){
    step=value;$$('[data-step]',form).forEach(s=>s.hidden=Number(s.dataset.step)!==step);
    $$('[data-step-label]',form).forEach(s=>{if(Number(s.dataset.stepLabel)===step)s.setAttribute('aria-current','step');else s.removeAttribute('aria-current');});
    back.hidden=step===1;next.hidden=step===3;confirm.hidden=step!==3;next.textContent=step===1?'Continuar':'Conferir parcelas';
    $('.modal-body',form).scrollTop=0;
  }
  function setBusy(value){
    busy=value;next.disabled=busy;back.disabled=busy;confirm.disabled=busy;$('#installment-fields').disabled=busy;
    form.setAttribute('aria-busy',String(busy));
  }
  function updateFields(){
    const credit=$('#f-modality').value==='credit';
    for(const [name,visible]of [['card_id',credit],['first_invoice_month',credit],['due_date',!credit],['account_id',!credit]]){
      const input=$(`#f-${name}`);input.closest('.field').hidden=!visible;input.disabled=!visible;
    }
    $('#installment-modality-help').textContent=credit?(activeCards.length?'A dívida ficará nas faturas deste cartão. O dinheiro sai da conta somente quando você pagar a fatura.':'Você precisa cadastrar um cartão em Cartões e faturas para usar esta modalidade.'):'Para boleto, carnê, empréstimo ou acordo. Nenhum cartão é necessário; escolha a conta ao pagar.';
    const perPart=$('#f-value_mode').value==='installment';
    $('label[for="f-amount_cents"]').textContent=perPart?'Valor de cada parcela (R$)':'Valor total (R$)';
    const help=$('#f-amount_cents').closest('.field').querySelector('small:not(.field-error)');
    help.textContent=perPart?'O total será este valor multiplicado pela quantidade de parcelas.':'O total será dividido pela quantidade de parcelas, preservando todos os centavos.';
    $('#installment-value-help').textContent=credit?'O cartão define o dia do vencimento de cada fatura. Se o dia não existir, será usado o último dia daquele mês. Confira as datas na próxima etapa.':'Vencimentos mensais usam o dia original. Se ele não existir em um mês menor, usa-se o último dia; nos meses seguintes, o dia original volta.';
    const card=byId('cards',$('#f-card_id').value);
    if(credit&&card){const input=$('#f-first_invoice_month');const purchase=$('#f-purchase_date').value||TODAY;if(!input.dataset.edited)input.value=suggestedCardDue(card,purchase).slice(0,7);}
  }
  function validDate(value){
    if(!/^\d{4}-\d{2}-\d{2}$/.test(value))return false;
    const [year,month,day]=value.split('-').map(Number);
    return year>=1900&&month>=1&&month<=12&&day>=1&&day<=new Date(Date.UTC(year,month,0)).getUTCDate();
  }
  function validate(which){
    clearErrors();
    if(which===1||which==='all'){
      if(!$('#f-description').value.trim())fieldError('description','Informe uma descrição para reconhecer esta conta.');
      if($('#f-modality').value==='credit'&&!$('#f-card_id').value)fieldError('card_id','Selecione o cartão da compra.');
    }
    if(which===2||which==='all'){
      const rawCount=$('#f-installments').value, rawPaid=$('#f-paid_installments').value;
      const count=Number(rawCount), paid=Number(rawPaid);
      if(!/^\d+$/.test(rawCount)||!Number.isInteger(count)||count<1||count>600)fieldError('installments','Informe uma quantidade inteira entre 1 e 600 parcelas.');
      if(!/^\d+$/.test(rawPaid)||!Number.isInteger(paid)||paid<0||paid>count)fieldError('paid_installments','Informe de zero até a quantidade total de parcelas já pagas.');
      try{
        const amount=cents($('#f-amount_cents').value);
        if(amount<=0)fieldError('amount_cents','O valor deve ser maior que zero.');
        else if($('#f-value_mode').value==='total'&&Number.isInteger(count)&&amount<count)fieldError('amount_cents','O total deve permitir pelo menos um centavo em cada parcela.');
        const total=$('#f-value_mode').value==='installment'?amount*count:amount;
        if(!Number.isSafeInteger(total)||total>10**14)fieldError('amount_cents','O total excede o limite permitido. Reduza o valor ou a quantidade.');
      }catch(error){fieldError('amount_cents',error.message);}
      if($('#f-modality').value==='outside'&&!validDate($('#f-due_date').value))fieldError('due_date','Informe uma data válida para o primeiro vencimento.');
      if($('#f-modality').value==='credit'&&!/^\d{4}-(0[1-9]|1[0-2])$/.test($('#f-first_invoice_month').value))fieldError('first_invoice_month','Informe o mês da primeira fatura.');
      if(!validDate($('#f-purchase_date').value))fieldError('purchase_date','Informe uma data válida para a compra ou registro.');
    }
    const invalid=$('[aria-invalid="true"]',form);
    if(invalid){$('#form-error').textContent='Confira os campos indicados. Seu preenchimento foi mantido.';const section=invalid.closest('[data-step]');if(section)showStep(Number(section.dataset.step));invalid.focus();return false;}
    return true;
  }
  function payload(){
    const raw=values(form), count=Number(raw.installments), value=cents(raw.amount_cents);
    const data={kind:'expense',description:raw.description.trim(),method:raw.modality==='credit'?'credit':'transfer',amount_cents:raw.value_mode==='installment'?value*count:value,installments:count,paid_installments:Number(raw.paid_installments),paid:false,value_mode:raw.value_mode,purchase_date:raw.purchase_date,competence_date:raw.purchase_date};
    if(raw.value_mode==='installment')data.installment_amount_cents=value;
    if(raw.modality==='credit'){data.card_id=raw.card_id;data.first_invoice_month=raw.first_invoice_month;}else{data.due_date=raw.due_date;if(raw.account_id)data.account_id=raw.account_id;}
    for(const key of ['merchant','category_id','person_id','notes'])if(raw[key]?.trim())data[key]=raw[key].trim();
    return data;
  }
  function presentPreview(result){
    const schedule=result.schedule||[];
    const unequal=new Set(schedule.map(p=>p.amount_cents)).size>1;
    const credit=result.modality==='credit';
    $('#installment-preview').innerHTML=`<h3>Confira antes de confirmar</h3><p class="form-note">${esc($('#f-description').value)} · ${credit?esc(result.card?.name||label('cards',$('#f-card_id').value)):'Parcelamento fora do cartão'}</p><dl class="installment-summary"><div><dt>Total da compra / dívida</dt><dd>${money(result.total_cents)}</dd></div><div><dt>Parcelas já pagas</dt><dd>${result.paid_installments} de ${schedule.length}</dd></div><div><dt>Parcelas restantes</dt><dd>${result.remaining_installments}</dd></div><div><dt>Saldo devedor inicial</dt><dd>${money(result.initial_debt_cents)}</dd></div><div><dt>Último vencimento previsto</dt><dd>${date(result.last_due_date)}</dd></div><div><dt>Modalidade vinculada</dt><dd>${credit?'Cartão de crédito':'Fora do cartão'}</dd></div></dl>${unequal?'<div class="notice">'+icon('info')+'<span>As parcelas têm valores diferentes para preservar o total exato. Confira cada valor abaixo.</span></div>':''}<div class="installment-schedule-wrap"><table id="installment-schedule"><thead><tr><th>Parcela</th><th>Vencimento</th><th>Valor</th><th>Situação</th></tr></thead><tbody>${schedule.map(p=>`<tr data-installment="${p.installment}"><td>${p.installment}/${schedule.length}</td><td>${date(p.due_date)}${p.invoice_month?`<small>Fatura ${esc(monthLabel(p.invoice_month,true))}</small>`:''}</td><td>${money(p.amount_cents)}</td><td>${p.already_paid?'<span class="tag tag-green">Paga anteriormente</span>':'Pendente'}</td></tr>`).join('')}</tbody></table></div><p class="form-note section-gap">Este cadastro não movimenta o saldo das contas. ${result.paid_installments?'As parcelas já pagas serão marcadas como anteriores ao aplicativo. ':''}As demais continuam pendentes até você confirmar o pagamento, mesmo que a data já tenha passado.</p>`;
  }
  function displayError(error){
    $('#form-error').textContent=errorText(error);
    const fields=error.details?.field_errors||error.details?.fields||{};
    for(const [name,text]of Object.entries(fields)){const key=name==='installment_amount_cents'?'amount_cents':name;fieldError(key,Array.isArray(text)?text.join(' '):String(text));}
    const invalid=$('[aria-invalid="true"]',form);
    if(invalid){showStep(Number(invalid.closest('[data-step]').dataset.step));invalid.focus();}else $('#form-error').focus();
  }
  form.addEventListener('input',event=>{
    if(busy)return;
    preview=null;previewPayload=null;
    if(event.target.id==='f-first_invoice_month')event.target.dataset.edited='true';
    if(event.target.matches('#f-value_mode,#f-modality,#f-card_id,#f-purchase_date'))updateFields();
    if(step===3)showStep(2);
  });
  form.addEventListener('change',event=>{if(event.target.matches('#f-value_mode,#f-modality,#f-card_id,#f-purchase_date'))updateFields();});
  back.addEventListener('click',()=>{if(!busy){clearErrors();showStep(step-1);}});
  next.addEventListener('click',async()=>{
    if(busy||!validate(step))return;
    if(step===1){showStep(2);return;}
    const data=payload();setBusy(true);
    try{const revision=ui.state.revision;preview=await mutate('entry.preview',data,undefined,revision);preview.revision=preview.revision??revision;previewPayload=data;presentPreview(preview);showStep(3);}
    catch(error){preview=null;previewPayload=null;displayError(error);}
    finally{setBusy(false);}
  });
  form.addEventListener('submit',async event=>{
    event.preventDefault();if(busy)return;
    if(step!==3){next.click();return;}
    if(!preview||!previewPayload){showStep(2);$('#form-error').textContent='Confira as parcelas novamente antes de confirmar.';return;}
    const signature=JSON.stringify(previewPayload);
    if(pendingSignature!==signature){pendingId=crypto.randomUUID();pendingSignature=signature;}
    setBusy(true);clearErrors();
    try{await mutate('entry.create',previewPayload,pendingId,preview.revision);modal.close();render();setToast('Conta parcelada cadastrada. Confira os vencimentos em Parcelamentos e dívidas.');}
    catch(error){
      if(error.status>=400&&error.status<500){pendingId=null;pendingSignature=null;}
      if(error.status===409){preview=null;previewPayload=null;showStep(2);}
      displayError(error);
    }finally{setBusy(false);}
  });
  updateFields();showStep(1);if(!modal.open)modal.showModal();$('#f-description').focus();
}

function showPaymentForm(kind,id,operation='payment'){
  let item=byId(kind==='invoice'?'invoices':'obligations',id);
  if(!item)throw Error('Este item não foi encontrado. Atualize o espaço.');
  if(kind==='obligation'&&item.card_id)return showPaymentForm('invoice',item.invoice_id,operation);
  if(!writable())throw Error('Seu acesso permite somente consulta.');
  if(!item.remaining_cents){setToast('Este compromisso já está liquidado.');return;}
  const accounts=list('accounts').filter(a=>a.status!=='archived');
  if(!accounts.length){setToast('Cadastre a conta usada para pagar ou receber antes de confirmar.');return showAccountForm();}
  const receiving=kind==='obligation'&&item.kind==='income';
  const card=byId('cards',item.card_id), entry=kind==='obligation'?byId('entries',item.entry_id):null;
  const selected=[card?.account_id,item.account_id,entry?.account_id].find(candidate=>candidate&&accounts.some(a=>String(a.id)===String(candidate)))||'';
  const title=receiving?'Confirmar recebimento':kind==='invoice'?'Pagar fatura':'Confirmar pagamento';
  const form=showDialog(title,kind==='invoice'?`${label('cards',item.card_id)} · ${monthLabel(item.month,true)}`:`${item.description} · Parcela ${item.installment}/${item.total_installments}`,`<div class="payment-target"><small>${kind==='invoice'?'Saldo pendente da fatura':receiving?'Valor a receber':`Saldo pendente da parcela ${item.installment}/${item.total_installments}`}</small><strong id="payment-pending">${money(item.remaining_cents)}</strong><span>Vencimento: ${date(item.due_date)}</span></div>${kind==='invoice'?`<div class="notice">${icon('card')}<span>Você está pagando a <b>fatura do cartão</b>, que pode reunir várias compras. O saldo mostrado é o da fatura completa. A saída de dinheiro será registrada uma única vez.</span></div>`:''}<div class="notice" id="payment-advance-notice" hidden>${icon('info')}<span id="payment-advance-copy"></span></div><div class="form-grid" id="payment-fields">${field('account_id',receiving?'Conta de destino':'Conta de pagamento','select',{full:true,required:true,value:selected,options:entityOptions('accounts','Selecione a conta')})}${field('paid_on',receiving?'Data do recebimento':'Data do pagamento','date',{required:true,value:TODAY,max:TODAY})}${field('paid_by',receiving?'Quem recebeu':'Quem pagou','select',{options:personOptions(),value:ui.session.user.id})}<input type="hidden" name="mode" id="payment-mode" value="full">${field('amount_cents',receiving?'Valor a receber (R$)':'Valor a pagar (R$)','text',{full:true,inputmode:'decimal',value:moneyInput(item.remaining_cents),help:'Informe um valor positivo até o saldo pendente. O restante continuará em aberto.'})}</div><div class="payment-options"><button type="button" class="text-btn" id="payment-partial">Alterar valor / pagamento parcial</button><button type="button" class="text-btn" id="payment-full" hidden>Usar saldo pendente total</button><button type="button" class="text-btn" id="payment-advance" hidden>Antecipar pagamento</button></div><p class="form-note" id="payment-account-help">${selected?'A conta vinculada foi selecionada. Confira antes de confirmar.':'Selecione a conta de pagamento para habilitar a confirmação.'}</p><div id="payment-preview" class="payment-preview" role="status" aria-live="polite"><p>Conferindo o pagamento…</p></div><button type="button" class="btn btn-soft btn-small" id="payment-preview-button" hidden>Conferir novamente</button>`,null);
  form.classList.add('payment-form');form.noValidate=true;
  const footer=$('.modal-footer',form);$('button',footer).textContent='Cancelar';
  const confirm=document.createElement('button');confirm.type='submit';confirm.id='payment-confirm';confirm.className='btn btn-primary';confirm.disabled=true;confirm.textContent=receiving?'Confirmar recebimento':'Confirmar pagamento';footer.append(confirm);
  const amountInput=$('#f-amount_cents',form), amountField=amountInput.closest('.field');amountField.hidden=true;
  let preview=null, previewPayload=null, previewSignature=null, pendingId=null, pendingSignature=null;
  let busy=false, previewBusy=false, needsReview=false, previewVersion=0, previewTimer=null;
  for(const input of $$('input:not([type=hidden]),select',form)){
    const container=input.closest('.field');if(!container)continue;
    const message=document.createElement('small');message.className='field-error';message.id=`${input.id}-error`;message.setAttribute('role','alert');container.append(message);input.setAttribute('aria-describedby',message.id);
  }
  function clearErrors(){
    $('#form-error').textContent='';$$('[aria-invalid]',form).forEach(i=>i.removeAttribute('aria-invalid'));$$('.field-error',form).forEach(i=>i.textContent='');
  }
  function fieldError(name,text){const input=$(`#f-${name}`,form);if(!input)return;input.setAttribute('aria-invalid','true');$(`#${input.id}-error`,form).textContent=text;if(input===amountInput)amountField.hidden=false;}
  function validDate(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value))return false;const [y,m,d]=value.split('-').map(Number);return y>=1900&&m>=1&&m<=12&&d>=1&&d<=new Date(Date.UTC(y,m,0)).getUTCDate();}
  function data(){
    const raw=values(form), value={mode:raw.mode,paid_on:raw.paid_on,paid_by:raw.paid_by||ui.session.user.id,operation};
    value[kind==='invoice'?'invoice_id':'obligation_id']=id;
    if(raw.account_id)value.account_id=raw.account_id;
    if(!validDate(raw.paid_on)||raw.paid_on>TODAY)fieldError('paid_on','Informe uma data válida até hoje; data futura permanece prevista.');
    if(raw.mode==='partial'){
      try{value.amount_cents=cents(raw.amount_cents);if(value.amount_cents<=0)fieldError('amount_cents','Informe um valor maior que zero.');else if(value.amount_cents>item.remaining_cents)fieldError('amount_cents','O valor não pode ultrapassar o saldo pendente.');}catch(error){fieldError('amount_cents',error.message);}
    }
    return $('[aria-invalid="true"]',form)?null:value;
  }
  function updateAdvanceHint(result){
    const future=!receiving&&(result?.requires_advance??(item.due_date?.slice(0,7)>$('#f-paid_on').value.slice(0,7)));
    const advanced=operation==='advance';
    $('#payment-advance-notice').hidden=!future&&!advanced;
    $('#payment-advance-copy').textContent=advanced?'Você escolheu antecipar este pagamento. O dinheiro sairá na data informada; não serão presumidos juros ou descontos.':kind==='invoice'?'Esta fatura vence em um mês futuro. Para pagá-la agora, escolha Antecipar pagamento.':'Esta parcela vence em um mês futuro. Para pagá-la agora, escolha Antecipar pagamento.';
    $('#payment-advance').hidden=!future||advanced;
    return future&&!advanced;
  }
  function renderPreview(result){
    const rows=[[kind==='invoice'?'Valor original dos itens da fatura':'Valor original da parcela',result.original_cents],...(result.adjusted_cents!==result.original_cents?[[kind==='invoice'?'Valor dos itens após ajustes':'Valor da parcela após ajustes',result.adjusted_cents]]:[]),[kind==='invoice'?'Valor liquidado da fatura':'Valor liquidado da parcela',result.paid_before_cents],[kind==='invoice'?'Saldo da fatura antes':'Saldo da parcela antes',result.pending_cents],[receiving?'Você vai receber':'Você vai pagar',result.amount_cents],[kind==='invoice'?'Saldo da fatura depois':'Saldo da parcela depois',result.remaining_after_cents]];
    const purchase=result.entry_id?byId('entries',result.entry_id):null;
    const purchaseRows=purchase?[
      [receiving?'Valor original do registro':'Valor original da compra',purchase.amount_cents],
      ...(!receiving&&purchase.adjusted_amount_cents!==undefined&&purchase.adjusted_amount_cents!==purchase.amount_cents?[['Valor da compra após ajustes',purchase.adjusted_amount_cents]]:[]),
      [receiving?'Valor liquidado do registro antes':'Valor liquidado da compra antes',purchase.paid_cents||0],
      [receiving?'Valor liquidado do registro depois':'Valor liquidado da compra depois',(purchase.paid_cents||0)+result.amount_cents],
      [receiving?'Saldo a receber do registro antes':'Dívida da compra antes',receiving?purchase.pending_cents:result.entry_debt_before_cents],
      [receiving?'Saldo a receber do registro depois':'Dívida da compra depois',receiving?purchase.pending_cents-result.amount_cents:result.entry_debt_after_cents]
    ]:[];
    const accountRows=result.account?[['Saldo da conta antes',result.account_balance_before_cents],['Saldo da conta depois',result.account_balance_after_cents]]:[];
    const debtRows=receiving?[]:[['Saldo devedor total antes',result.total_debt_before_cents],['Saldo devedor total depois',result.total_debt_after_cents]];
    const container=$('#payment-preview');
    container.dataset.amountCents=String(result.amount_cents);container.dataset.revision=String(result.revision);container.dataset.remainingAfterCents=String(result.remaining_after_cents);
    container.innerHTML=`<h3>Confira o resultado</h3><dl class="payment-summary">${[...rows,...purchaseRows,...debtRows,...accountRows].map(([text,value])=>`<div><dt>${esc(text)}</dt><dd>${money(value)}</dd></div>`).join('')}</dl>${!receiving&&result.entry_id?`<p class="form-note">Parcelas quitadas: ${result.paid_installments_before} → ${result.paid_installments_after}. Restantes: ${result.remaining_installments_after}.</p>`:''}${kind==='invoice'&&result.allocations?.length?`<details class="payment-allocations"><summary>Como o pagamento será distribuído</summary>${result.allocations.map(part=>`<div><span>${esc(part.description)} · ${part.installment}/${part.total_installments}</span><b>${money(part.amount_cents)}</b></div>`).join('')}</details>`:''}${result.remaining_after_cents>0?'<p class="payment-partial-note">Confirmação parcial: o saldo restante continuará pendente.</p>':'<p class="payment-partial-note">O saldo deste compromisso será liquidado.</p>'}`;
    $('#payment-pending').textContent=money(result.pending_cents);
    if($('#payment-mode').value==='full')amountInput.value=moneyInput(result.amount_cents);
    const blocked=updateAdvanceHint(result);
    const verb=receiving?'Confirmar recebimento':'Confirmar pagamento';
    confirm.textContent=`${verb} de ${money(result.amount_cents)}`;
    confirm.disabled=busy||blocked||result.can_confirm===false||!$('#f-account_id').value;
    $('#payment-account-help').textContent=$('#f-account_id').value?'Confira a conta, a data e o saldo após a confirmação.':'Selecione uma conta para habilitar a confirmação.';
  }
  function showError(error){
    $('#form-error').textContent=errorText(error);
    for(const [name,text]of Object.entries(error.details?.field_errors||{}))fieldError(name,Array.isArray(text)?text.join(' '):String(text));
  }
  function setBusy(value){
    busy=value;form.setAttribute('aria-busy',String(value));
    $$('input,select,button',form).forEach(control=>control.disabled=value);
    if(!value){confirm.disabled=!preview||needsReview||preview?.can_confirm===false||updateAdvanceHint(preview)||!$('#f-account_id').value;$('#payment-preview-button').disabled=previewBusy;}
  }
  async function refreshPreview(manual=false){
    clearTimeout(previewTimer);if(busy||!form.isConnected||!modal.open)return;
    if(needsReview&&!manual)return;
    clearErrors();const request=data();preview=null;previewPayload=null;previewSignature=null;confirm.disabled=true;
    const container=$('#payment-preview');delete container.dataset.amountCents;delete container.dataset.revision;
    if(!request){container.innerHTML='<p>Confira os campos indicados para atualizar os valores.</p>';return;}
    const version=++previewVersion;previewBusy=true;$('#payment-preview-button').disabled=true;container.innerHTML='<p>Conferindo o pagamento…</p>';
    try{
      const revision=ui.state.revision;const result=await mutate('payment.preview',request,undefined,revision);
      if(version!==previewVersion||!form.isConnected)return;
      result.revision=result.revision??revision;preview=result;previewPayload={...result.commit_data};
      if(operation==='payment')delete previewPayload.operation;
      previewSignature=JSON.stringify(request);needsReview=false;$('#payment-preview-button').hidden=true;
      item=byId(kind==='invoice'?'invoices':'obligations',id)||item;renderPreview(result);
    }catch(error){
      if(version!==previewVersion||!form.isConnected)return;
      if(error.status===409)needsReview=true;
      container.innerHTML='<p>O pagamento ainda não foi confirmado.</p>';$('#payment-preview-button').hidden=false;showError(error);
    }finally{if(version===previewVersion){previewBusy=false;$('#payment-preview-button').disabled=false;}}
  }
  function schedulePreview(){
    preview=null;previewPayload=null;previewSignature=null;confirm.disabled=true;previewVersion++;
    delete $('#payment-preview').dataset.amountCents;delete $('#payment-preview').dataset.revision;
    clearTimeout(previewTimer);if(!needsReview)previewTimer=setTimeout(()=>refreshPreview(),200);
  }
  $('#payment-partial').addEventListener('click',()=>{
    $('#payment-mode').value='partial';amountField.hidden=false;$('#payment-partial').hidden=true;$('#payment-full').hidden=false;amountInput.focus();amountInput.select();schedulePreview();
  });
  $('#payment-full').addEventListener('click',()=>{
    $('#payment-mode').value='full';amountField.hidden=true;$('#payment-partial').hidden=false;$('#payment-full').hidden=true;amountInput.value=moneyInput(item.remaining_cents);schedulePreview();
  });
  $('#payment-advance').addEventListener('click',()=>{operation='advance';needsReview=false;updateAdvanceHint();schedulePreview();});
  $('#payment-preview-button').addEventListener('click',()=>refreshPreview(true));
  for(const control of $$('input:not([type=hidden]),select',form))control.addEventListener('input',()=>{if(!busy)schedulePreview();});
  form.addEventListener('submit',async event=>{
    event.preventDefault();if(busy||previewBusy)return;
    clearErrors();const current=data();if(!current)return;
    if(!$('#f-account_id').value){fieldError('account_id','Selecione a conta usada para esta confirmação.');return;}
    if(!preview||!previewPayload||needsReview||JSON.stringify(current)!==previewSignature){$('#form-error').textContent='Confira os valores novamente antes de confirmar.';$('#payment-preview-button').hidden=false;return;}
    if(preview.can_confirm===false||updateAdvanceHint(preview))return;
    const signature=JSON.stringify(previewPayload);
    if(signature!==pendingSignature){pendingId=crypto.randomUUID();pendingSignature=signature;}
    const action=operation==='advance'?'payment.advance':kind==='invoice'?'invoice.pay':'obligation.pay';
    setBusy(true);
    try{
      await mutate(action,previewPayload,pendingId,preview.revision);modal.close();render();setToast(receiving?'Recebimento confirmado. Os saldos foram atualizados.':operation==='advance'?'Antecipação confirmada. Os saldos foram atualizados.':'Pagamento confirmado. Os saldos foram atualizados.');
    }catch(error){
      if(error.status>=400&&error.status<500){pendingId=null;pendingSignature=null;}
      if(error.status===409){preview=null;previewPayload=null;needsReview=true;$('#payment-preview-button').hidden=false;delete $('#payment-preview').dataset.amountCents;delete $('#payment-preview').dataset.revision;}
      showError(error);
    }finally{setBusy(false);}
  });
  updateAdvanceHint();refreshPreview();
}
function showCategoryForm(){showDialog('Nova categoria','Agrupe seus registros para entender seus hábitos.',`<div class="form-grid">${field('name','Nome da categoria','text',{full:true,required:true,maxlength:120,placeholder:'Ex.: Delivery'})}${field('parent_id','Categoria principal (opcional)','select',{full:true,options:entityOptions('categories','Nenhuma — categoria principal')})}</div>`,async(d,id)=>{if(!d.parent_id)delete d.parent_id;await mutate('category.create',d,id);},'Criar categoria');}
function showBudgetForm(){showDialog('Um plano para o seu mês','Defina um limite de consumo por categoria.',`<div class="form-grid">${field('month','Mês','month',{value:ui.month,required:true})}${field('amount_cents','Orçamento (R$)','text',{required:true,inputmode:'decimal',placeholder:'0,00'})}${field('category_id','Categoria','select',{full:true,required:true,options:entityOptions('categories')})}</div><p class="form-note section-gap">O acompanhamento usa a data de compra. Definir novamente substitui o orçamento da mesma categoria e mês.</p>`,async(d,id)=>{d.amount_cents=cents(d.amount_cents);if(d.amount_cents<0)throw Error('O orçamento não pode ser negativo.');await mutate('budget.set',d,id);},'Salvar orçamento');}
function showSimulation(){showDialog('E se eu fizer uma compra?','Veja o impacto nos próximos meses, sem registrar uma dívida.',`<div class="form-grid">${field('amount_cents','Valor total (R$)','text',{inputmode:'decimal',required:true,placeholder:'1.200,00'})}${field('installments','Número de parcelas','number',{min:1,max:360,value:6,required:true})}${field('due_date','Primeiro vencimento','date',{required:true,value:`${ui.month<CURRENT_MONTH?CURRENT_MONTH:ui.month}-20`,full:true})}</div><p class="form-note section-gap">Sem juros presumidos. A simulação divide o total em centavos exatos e mantém as demais premissas da sua projeção.</p>`,async(d,id)=>{d.amount_cents=cents(d.amount_cents);d.installments=Number(d.installments);d.months=ui.months;d.start_month=ui.month<CURRENT_MONTH?CURRENT_MONTH:ui.month;ui.simulation=await mutate('simulation',d,id);ui.page='future';},'Simular cenário');}
async function loadTechnicalUsers(append=false){
  if(!technicalAdmin())throw Error('Seu acesso não permite administrar contas de usuário.');
  const offset=append?ui.technicalNextOffset:0;if(append&&offset===null)return;
  const result=await api(`/api/technical/users?offset=${offset}`);
  ui.technicalUsers=append?[...(ui.technicalUsers||[]),...result.users]:result.users;
  ui.technicalTotal=result.total;ui.technicalNextOffset=result.next_offset;render();
}
function technicalUsersPage(){
  if(!technicalAdmin())return empty('Acesso técnico restrito','Somente a administração técnica pode consultar contas de usuário.','','','shield');
  const users=ui.technicalUsers;
  return `${heading('Contas de usuário','Administração técnica do acesso ao Organiza.')}<section class="panel"><div class="notice">${icon('shield')}<span>Ativar aprova o acesso ao aplicativo. Bloquear impede novos acessos e encerra o uso das sessões existentes, preservando o histórico. A participação em espaços é gerenciada separadamente em Configurações > Participantes.</span></div><p class="form-note section-gap">Contas sem acesso incluem solicitações aguardando aprovação e contas bloqueadas.</p>${users===null?'<p class="form-note section-gap">Carregando contas de usuário…</p>':`<div class="table-scroll section-gap"><table class="technical-users"><thead><tr><th>ID</th><th>Usuário</th><th>Situação</th><th>Acesso técnico</th><th></th></tr></thead><tbody>${users.map(user=>`<tr><td>#${esc(user.id)}</td><td><b>${esc(user.display_name)}</b><small>@${esc(user.username)}</small></td><td><span class="tag${user.is_active?' tag-green':' tag-red'}">${user.is_active?'Ativo':'Sem acesso'}</span></td><td>${user.technical_admin?'Administrador técnico':'Usuário'}</td><td>${user.id===ui.session.user.id?'<span class="muted">Seu acesso</span>':`<button class="text-btn" data-action="technical-user-status" data-id="${esc(user.id)}">${user.is_active?'Bloquear':'Ativar acesso'}</button>`}</td></tr>`).join('')}</tbody></table></div><p class="form-note section-gap">${users.length} de ${ui.technicalTotal} contas.</p>${ui.technicalNextOffset!==null?button('load-technical-users','Carregar mais','down','soft'):''}`}</section>`;
}
function showUserStatusForm(id){
  const user=(ui.technicalUsers||[]).find(item=>String(item.id)===String(id));
  if(!technicalAdmin()||!user)throw Error('Conta de usuário não disponível para este acesso.');
  const active=!user.is_active;
  showDialog(active?'Aprovar acesso do usuário':'Bloquear acesso do usuário',`@${user.username} · Usuário #${user.id}`,`<p class="form-note">${active?'O usuário poderá entrar no Organiza com sua própria senha. A associação aos espaços e seus perfis continuam separados.':'O usuário deixará de acessar todos os seus espaços. Os dados financeiros, a autoria e o histórico serão preservados.'}</p>`,async()=>{await api(`/api/technical/users/${encodeURIComponent(id)}/status`,'POST',{is_active:active});await loadTechnicalUsers();},active?'Ativar acesso':'Confirmar bloqueio','Acesso do usuário atualizado.');
}
function showMemberForm(){showDialog('Adicionar participante','Cada pessoa usa seu próprio acesso.',`<p class="form-note">A pessoa precisa criar o acesso antes de ser adicionada. Todos os participantes terão visão dos dados deste espaço. Não há envio de convite externo nesta versão.</p><div class="form-grid">${field('username','Nome de usuário da pessoa','text',{required:true,full:true,placeholder:'usuario.da.pessoa'})}${field('role','Perfil de acesso','select',{full:true,options:[['collaborator','Colaborador — registra e consulta'],['reader','Leitor — apenas consulta'],['admin','Administrador — gerencia o espaço']]})}</div>`,async d=>{await api(`/api/spaces/${ui.spaceId}/members`,'POST',d);await loadState(false);},'Adicionar participante');}
function showEntryDetail(id){const e=byId('entries',id);if(!e)throw Error('Registro não encontrado.');const obligations=list('obligations').filter(o=>o.entry_id===id);const payments=list('payments').filter(p=>p.entry_id===id||obligations.some(o=>o.id===p.obligation_id)||(p.allocations||[]).some(a=>obligations.some(o=>o.id===a.obligation_id)));showDialog(e.description,'Compra original, obrigações e confirmações relacionadas.',`<dl class="detail-list"><div><dt>Valor original</dt><dd>${money(e.amount_cents)}</dd></div>${e.adjusted_amount_cents!==undefined&&e.adjusted_amount_cents!==e.amount_cents?`<div><dt>Valor após ajustes</dt><dd>${money(e.adjusted_amount_cents)}</dd></div>`:""}<div><dt>Valor liquidado</dt><dd>${money(e.paid_cents||0)}</dd></div><div><dt>Categoria</dt><dd>${esc(label('categories',e.category_id))}</dd></div><div><dt>Estabelecimento</dt><dd>${esc(e.merchant||'Não informado')}</dd></div><div><dt>Pessoa responsável</dt><dd>${esc(person(e.person_id))}</dd></div><div><dt>Registrado por</dt><dd>${esc(person(e.created_by))}</dd></div><div><dt>Compra / competência</dt><dd>${date(e.purchase_date)} / ${date(e.competence_date)}</dd></div><div><dt>Forma de pagamento</dt><dd>${esc(entryMethodLabel(e))}</dd></div><div><dt>${e.kind==="income"?"Saldo a receber":"Saldo devedor"}</dt><dd>${money(e.kind==="income"?e.pending_cents:e.debt_cents)}</dd></div></dl>${e.notes?`<p class="form-note section-gap">${esc(e.notes)}</p>`:''}<div class="divider"></div><h3>Parcelas e obrigações</h3>${writable()&&e.recurrence_id?`<button class="text-btn" data-action="occurrence-edit" data-id="${esc(e.id)}">Editar somente esta ocorrência</button>`:''}${obligations.length?obligations.map(o=>`<div class="participant obligation-item" data-obligation-id="${esc(o.id)}"><div class="item-body"><b>${o.installment}/${o.total_installments} · ${date(o.due_date)}</b><div class="obligation-values">${obligationValues(o)}</div>${o.initial_paid_cents?'<small>Inclui pagamento anterior ao aplicativo</small>':''}</div><div class="obligation-controls"><div class="badges">${settlementBadge(o)}${overdueNote(o)}</div>${paymentActions(o)}${writable()&&o.status!=='cancelled'?`<button class="text-btn" data-action="adjust-obligation" data-id="${esc(o.id)}">Ajustar</button>`:''}</div></div>`).join(''):empty('Sem parcelas vinculadas','Transferências próprias são registradas diretamente no caixa.','','','arrows',true)}${payments.length?`<div class="divider"></div><h3>Confirmações e estornos</h3>${payments.map(p=>`<div class="participant"><div class="item-body"><b>${money(p.amount_cents)} · ${date(p.paid_on)}</b><small>${p.reversed||p.reversed_at||p.status==='reversed'?'Estornado':'Confirmação registrada'}${p.paid_by?' · '+esc(person(p.paid_by)):''}</small></div>${writable()&&!p.reversed&&!p.reversed_at&&p.status!=='reversed'?`<button class="text-btn" data-action="reverse-payment" data-id="${esc(p.id)}">Estornar</button>`:''}</div>`).join('')}`:''}${writable()&&e.status!=='cancelled'?`<div class="divider"></div><button class="btn btn-danger btn-small" data-action="cancel-entry" data-id="${esc(id)}">Cancelar registro</button><p class="form-note" style="margin-top:9px">Cancelamentos preservam o histórico. Pagamentos existentes devem ser estornados antes.</p>`:''}`,null);}
function showInvoiceDetail(id){const invoice=byId('invoices',id);if(!invoice)throw Error('Fatura não encontrada.');const obligations=list('obligations').filter(o=>o.invoice_id===id);const payments=list('payments').filter(p=>p.invoice_id===id);showDialog(`${label('cards',invoice.card_id)} · ${monthLabel(invoice.month,true)}`,'Fatura e parcelas vinculadas a este cartão.',`<dl class="detail-list"><div><dt>Fechamento</dt><dd>${date(invoice.closing_date)}</dd></div><div><dt>Vencimento</dt><dd>${date(invoice.due_date)}</dd></div><div><dt>Total da fatura</dt><dd>${money(invoice.amount_cents)}</dd></div><div><dt>Valor liquidado</dt><dd>${money(invoice.paid_cents)}</dd></div><div><dt>Saldo pendente</dt><dd>${money(invoice.remaining_cents)}</dd></div></dl><div class="divider"></div><h3>Compras e parcelas</h3>${obligations.map(o=>`<div class="participant"><div class="item-body"><b>${esc(o.description)}</b><small>${o.installment}/${o.total_installments} · ${esc(label('categories',o.category_id))}</small></div><b>${money(o.amount_cents)}</b></div>`).join('')}${writable()?`<div class="heading-actions section-gap">${invoice.remaining_cents>0?button('pay-invoice','Pagar fatura','card','primary',`data-id="${esc(id)}"`):''}${button('edit-invoice','Ajustar fatura','calendar','soft',`data-id="${esc(id)}"`)}</div>`:''}${payments.length?`<div class="divider"></div><h3>Pagamentos registrados</h3>${payments.map(p=>`<div class="participant"><div class="item-body"><b>${money(p.amount_cents)} · ${date(p.paid_on)}</b><small>${p.reversed||p.reversed_at||p.status==='reversed'?'Estornado':'Confirmado'}</small></div>${writable()&&!p.reversed&&!p.reversed_at&&p.status!=='reversed'?`<button class="text-btn" data-action="reverse-payment" data-id="${esc(p.id)}">Estornar</button>`:''}</div>`).join('')}`:''}`,null);}
function showInvoiceEdit(id){const i=byId('invoices',id);const movable=list('obligations').filter(o=>o.card_id===i.card_id&&o.invoice_id!==id&&o.remaining_cents===o.amount_cents&&o.status!=='cancelled');showDialog('Ajustar fatura','Corrija datas ou a atribuição de uma parcela pendente.',`<div class="form-grid">${field('closing_date','Data de fechamento','date',{required:true,value:i.closing_date})}${field('due_date','Data de vencimento','date',{required:true,value:i.due_date})}${field('move_obligation','Mover uma parcela para esta fatura (opcional)','select',{full:true,options:[['','Não mover parcelas'],...movable.map(o=>[o.id,`${o.description} · ${o.installment}/${o.total_installments} · ${date(o.due_date)} · ${money(o.amount_cents)}`])]})}</div><p class="form-note section-gap">Apenas parcelas não pagas do mesmo cartão podem mudar de fatura. As alterações ficam registradas no histórico.</p>`,async(d,rid)=>{const payload={invoice_id:id,due_date:d.due_date,closing_date:d.closing_date};if(d.move_obligation)payload.obligation_ids=[d.move_obligation];await mutate('invoice.update',payload,rid);},'Salvar ajuste');}
function showAdjustment(id){const o=byId('obligations',id);showDialog('Ajustar uma obrigação',`${o.description} · parcela ${o.installment}/${o.total_installments}`,`<p class="form-note">Pendente: ${money(o.remaining_cents)}. Descontos e encargos mudam a obrigação com histórico; não presumem quitação por passagem de tempo. Para antecipar, confirme o pagamento na fatura ou no calendário.</p><div class="form-grid">${field('kind','Tipo de ajuste','select',{options:[['discount','Desconto informado'],['fee','Encargo informado'],['refund','Reembolso / estorno informado']]})}${field('amount_cents','Valor do ajuste (R$)','text',{inputmode:'decimal',required:true,placeholder:'0,00'})}${field('reason','Motivo do ajuste','textarea',{full:true,required:true,maxlength:500})}${field('account_id','Conta (reembolso já pago)','select',{full:true,options:entityOptions('accounts','Não se aplica')})}${field('paid_on','Data do reembolso (se aplicável)','date',{value:TODAY,full:true})}</div>`,async(d,rid)=>{d.obligation_id=id;d.amount_cents=cents(d.amount_cents);if(!d.account_id)delete d.account_id;await mutate('obligation.adjust',d,rid);},'Registrar ajuste');}
function showReason(action,id,title,description){showDialog(title,description,`${field('reason','Motivo','textarea',{full:true,required:true,maxlength:500,placeholder:'Descreva o motivo para preservar o histórico.'})}`,async(d,rid)=>{d[action==='payment.reverse'?'payment_id':'entry_id']=id;if(action==='payment.reverse')d.occurred_on=TODAY;await mutate(action,d,rid);},'Confirmar');}
function showRecurrenceEdit(id){const r=byId('recurrences',id);showDialog('Alterar recorrências futuras','Os registros já confirmados preservam seus valores.',`<div class="form-grid">${field('from_date','A partir de','date',{required:true,value:TODAY})}${field('amount_cents','Novo valor mensal (R$)','text',{required:true,inputmode:'decimal',value:moneyInput(r.template?.amount_cents||byId('entries',r.entry_id)?.amount_cents||0)})}</div><p class="form-note section-gap">A alteração alcança as ocorrências pendentes a partir da data informada. Para uma ocorrência específica, abra o registro e ajuste a obrigação com um motivo.</p>`,async(d,rid)=>{await mutate('recurrence.update',{recurrence_id:id,scope:'future',from_date:d.from_date,changes:{amount_cents:cents(d.amount_cents)}},rid);},'Alterar futuras');}
async function delegate(event){const target=event.target.closest('[data-action],[data-page],[data-filter]');if(!target)return;if(target.disabled)return;event.preventDefault();try{if(target.dataset.page){ui.page=target.dataset.page;ui.filter='all';ui.search='';if(ui.page==='user-admin'&&!technicalAdmin())throw Error('Seu acesso não permite administrar contas de usuário.');render();if(ui.page==='user-admin')await loadTechnicalUsers();window.scrollTo({top:0,behavior:'instant'});return;}if(target.dataset.filter){ui.filter=target.dataset.filter;render();return;}const id=target.dataset.id;switch(target.dataset.action){case'auth-toggle':ui.authMode=ui.authMode==='login'?'register':'login';renderAuth();break;case'logout':await api('/api/auth/logout','POST',{});ui.spaceId=null;ui.state=null;ui.simulation=null;await session();break;case'menu':$('#sidebar').classList.toggle('open');target.setAttribute('aria-expanded',$('#sidebar').classList.contains('open'));break;case'close-modal':modal.close();break;case'refresh':await session();setToast('Dados atualizados.');break;case'new-space':showSpaceForm();break;case'new-account':showAccountForm();break;case'new-card':showCardForm();break;case'edit-account':showEntityEdit('account',id);break;case'edit-card':showEntityEdit('card',id);break;case'edit-category':showEntityEdit('category',id);break;case'new-entry':showEntryForm();break;case'pix-entry':showEntryForm('pix');break;case'installment-entry':showEntryForm('installment');break;case'new-category':showCategoryForm();break;case'new-budget':showBudgetForm();break;case'new-member':showMemberForm();break;case'technical-user-status':showUserStatusForm(id);break;case'load-technical-users':await loadTechnicalUsers(true);break;case'pay-invoice':showPaymentForm('invoice',id);break;case'pay-obligation':showPaymentForm('obligation',id);break;case'advance-invoice':showPaymentForm('invoice',id,'advance');break;case'advance-obligation':showPaymentForm('obligation',id,'advance');break;case'entry-detail':showEntryDetail(id);break;case'invoice-detail':showInvoiceDetail(id);break;case'edit-invoice':showInvoiceEdit(id);break;case'adjust-obligation':showAdjustment(id);break;case'reverse-payment':showReason('payment.reverse',id,'Estornar confirmação','A saída ou entrada de caixa será revertida, mantendo o histórico.');break;case'cancel-entry':showReason('entry.cancel',id,'Cancelar registro','O registro permanece no histórico. Confirmações existentes devem ser estornadas antes.');break;case'recurrence-edit':showRecurrenceEdit(id);break;case'occurrence-edit':showOccurrenceEdit(id);break;case'simulate':showSimulation();break;case'clear-simulation':ui.simulation=null;render();break;case'remove-member':{const member=byId('members',id);showDialog('Remover participante',`${member.display_name||member.username} perderá acesso a este espaço.`,`<p class="form-note">Os registros e a autoria já existentes permanecem no histórico.</p>`,async()=>{await api(`/api/spaces/${ui.spaceId}/members/${id}`,'DELETE',{});await loadState(false);},'Remover acesso');break;}}}catch(e){setToast(errorText(e));}}
function bindActions(){app.onclick=delegate;modal.onclick=delegate;const search=$('#search-entries');if(search)search.addEventListener('input',e=>{const pos=e.target.selectionStart;ui.search=e.target.value;render();const current=$('#search-entries');current.focus();current.setSelectionRange(pos,pos);});const basis=$('#report-basis');if(basis)basis.addEventListener('change',e=>{ui.reportBasis=e.target.value;render();});const horizon=$('#projection-months');if(horizon)horizon.addEventListener('change',async e=>{ui.months=Number(e.target.value);ui.simulation=null;try{await loadState();}catch(err){setToast(errorText(err));}});$$('.role-change').forEach(select=>select.addEventListener('change',async e=>{const input=e.target;input.disabled=true;try{await api(`/api/spaces/${ui.spaceId}/members/${input.dataset.id}`,'POST',{role:input.value});await loadState();setToast('Perfil de acesso atualizado.');}catch(err){input.value=input.dataset.old;setToast(errorText(err));}finally{input.disabled=false;}}));}
document.addEventListener('click',e=>{const sidebar=$('#sidebar');if(sidebar?.classList.contains('open')&&!sidebar.contains(e.target)&&!e.target.closest('[data-action="menu"]'))sidebar.classList.remove('open');});
session().catch(e=>{app.innerHTML=`<main id="main" class="main-content"><div class="error-panel"><h1>Vamos reconectar seu espaço.</h1><p>${esc(e.message)}</p><button class="btn btn-soft section-gap" id="retry-boot">Tentar novamente</button></div></main>`;$('#retry-boot').addEventListener('click',()=>location.reload());});
